type Job={slug:string;keyword:string;make:string;model:string;category:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source;sources?:Source[];reviewed?:string;diagram?:"wheel"|"spark"|"firing"|"oil"|"timing"|"main";engine?:boolean};
const jobs:Job[]=[
  {slug:"hyundai/kona/oil-capacity",keyword:"hyundai kona oil capacity specifications",make:"Hyundai",model:"2024 Kona",category:"Fluid Capacities",title:"2024 Hyundai Kona Oil Capacity: 2.0L vs. 1.6 Turbo",answer:"For a drain-and-refill, Hyundai specifies 4.5 US qt (4.3 L) for the 2024 Kona Smartstream 2.0L Atkinson engine and 5.1 US qt (4.8 L) for the Smartstream 1.6L T-GDi.",scope:"These values are from the U.S.-market 2024 SX2 Kona manual. They do not apply to the electric Kona, Kona N, another market's 1.0L engine or an earlier generation. Identify the engine before opening bottles because the two gasoline rows differ by 0.6 qt.",detail:"Both gasoline engines call for full-synthetic SAE 0W-20 meeting API SN PLUS/SP or ILSAC GF-6 in this manual. Treat the listed amount as a refill reference: install the correct filter and drain-plug sealing part, add most of the quantity, circulate the oil, inspect for leaks, wait on level ground and finish at the dipstick mark. Never force the entire bottle count into an engine already reading full.",values:[{label:"2.0L Atkinson drain-and-refill",value:"4.5 US qt",note:"4.3 L"},{label:"1.6L T-GDi drain-and-refill",value:"5.1 US qt",note:"4.8 L"},{label:"Required viscosity",value:"SAE 0W-20",note:"Both gasoline engine rows"},{label:"Oil quality",value:"API SN PLUS/SP or ILSAC GF-6",note:"Full synthetic required"}],source:hyundaiKona2024,diagram:"oil"},
  {slug:"ford/escape/spark-plug-gap",keyword:"ford escape spark plug gap specs",make:"Ford",model:"2019 Escape 1.5L EcoBoost",category:"Ignition Specs",title:"Ford Escape Spark Plug Gap Specs by Engine",answer:"Ford specifies 0.025–0.029 in (0.65–0.75 mm) for the 2019 Escape 1.5L four-cylinder EcoBoost.",scope:"The exact range applies to the 2019 Escape's 1.5L four-cylinder EcoBoost. The later 1.5L three-cylinder, 1.6L and 2.0L EcoBoost, 2.5L naturally aspirated engine and hybrids have separate rows.",detail:"Confirm the Motorcraft-equivalent plug for the VIN before measuring. Use a wire gauge, handle the fine-wire center electrode carefully and replace a plug whose electrode or insulator is damaged rather than forcing it to the range.",values:[{label:"2019 Escape 1.5L EcoBoost I4",value:"0.025–0.029 in",note:"0.65–0.75 mm; Ford owner manual"},{label:"Firing order",value:"1-3-4-2",note:"Confirms four-cylinder 1.5L"},{label:"2020+ 1.5L three-cylinder",value:"Separate specification",note:"Different engine architecture"},{label:"2.0L / 2.5L / hybrid",value:"Use exact engine row",note:"Do not transfer this gap"}],source:ford2019Escape15,diagram:"spark",engine:true},
  {slug:"chevrolet/colorado/towing-capacity",keyword:"chevy colorado towing capacity chart",make:"Chevrolet",model:"2023 Colorado",category:"Vehicle Specifications",title:"2023 Chevy Colorado Towing Capacity Chart by 2.7L Engine Tune",answer:"Chevrolet rates the 2023 Colorado at 3,500 lb with the 237-hp 2.7L Turbo and as high as 7,700 lb with the 2.7L Turbo Plus or High-Output tune. The off-road ZR2 is capped at 6,000 lb even though it uses the High-Output engine.",scope:"This chart is for the redesigned U.S.-market 2023 Colorado. It does not apply to a 2022-or-earlier truck, a different model year or a truck lacking the equipment required by its trailering label and guide.",detail:"Treat the engine badge as only the first check. Cab, trim, drivetrain, axle, hitch and trailering equipment still matter, and occupants, cargo, accessories and trailer tongue weight consume payload. Confirm the truck's certification labels and owner information before connecting a trailer.",values:[{label:"2.7L Turbo",value:"3,500 lb",note:"237 hp; 259 lb-ft"},{label:"2.7L Turbo Plus",value:"7,700 lb",note:"310 hp; 390 lb-ft"},{label:"2.7L Turbo High-Output",value:"Up to 7,700 lb",note:"310 hp; 430 lb-ft"},{label:"ZR2 with High-Output",value:"6,000 lb max",note:"Off-road configuration has a lower limit"}],source:chevroletColorado2023,diagram:"main"},
  {slug:"dodge/dart/firing-order",keyword:"dodge dart firing order specifications",make:"Dodge",model:"2013 Dodge Dart 2.0L Tigershark I4",category:"Firing Order",title:"2013 Dodge Dart 2.0 Firing Order and Cylinder Numbering",answer:"The 2013 Dodge Dart 2.0L inline-four firing order is 1-3-4-2. Cylinder 1 is at the timing-drive end of the engine, followed by cylinders 2, 3 and 4 toward the transmission.",scope:"This page is anchored to the 2013 Dart 2.0L Tigershark application. The 1.4L turbo and 2.4L are also inline-fours but use different timing, ignition and service components; classic rear-wheel-drive Darts with Slant Six or V8 engines are entirely separate.",detail:"The car uses coil-on-plug ignition, so there is no distributor cap to wire in firing-order sequence. Use the order to interpret combustion events and use physical cylinder numbering when diagnosing P0301–P0304; P0303 means cylinder 3, not the third event in 1-3-4-2.",values:[{label:"Firing order",value:"1-3-4-2",note:"2013 Dart 2.0L inline-four"},{label:"Cylinder numbering",value:"1-2-3-4",note:"Timing-drive end toward transmission"},{label:"Ignition layout",value:"Coil-on-plug",note:"No distributor-wire routing"},{label:"P0301 through P0304",value:"Physical cylinder number",note:"Not firing-sequence position"}],source:dodgeDart2013Firing,diagram:"firing",engine:true},
  {slug:"honda/fit/oil-capacity",keyword:"honda fit oil capacity specifications",make:"Honda",model:"2016 Fit 1.5L",category:"Fluid Capacities",title:"2016 Honda Fit Oil Capacity: Exact 1.5L Refill Specs",answer:"Honda specifies 3.5 US qt (3.3 L) when the oil filter is changed on a 2016 Fit 1.5L. An oil-only change is 3.3 US qt (3.1 L).",scope:"These quantities are for the U.S.-market 2016 Fit with the 1,498 cc engine. Other Fit/Jazz generations and markets are not silently grouped into this row; identify the model year before using it.",detail:"Install a new drain-plug washer, refill with the specified 0W-20 oil, run the engine and inspect the filter and drain plug for leaks. Stop the engine, allow drain-back on level ground, and use the dipstick as the final level check rather than treating the published refill quantity as an instruction to overfill.",values:[{label:"Oil and filter change",value:"3.5 US qt",note:"3.3 L; 2016 Honda specification"},{label:"Oil change, filter retained",value:"3.3 US qt",note:"3.1 L"},{label:"Recommended viscosity",value:"SAE 0W-20",note:"Use oil meeting the manual's quality requirement"},{label:"Final verification",value:"Dipstick upper mark",note:"Check after circulation and drain-back"}],source:hondaFit2016,diagram:"oil"},
  {slug:"bmw/x3/brake-rotor-size",keyword:"bmw x3 brake rotor size chart",make:"BMW",model:"2013 X3 xDrive28i F25",category:"Brake Specifications",title:"2013 BMW X3 xDrive28i Front Rotor Size and Wear Limit",answer:"The standard covered 2013 BMW X3 xDrive28i F25 front brake uses a 328 x 28 mm ventilated rotor. BMW's service information gives 26.4 mm as the minimum thickness for this row.",scope:"This exact figure applies only after the VIN/EPC confirms the 328-mm standard brake. Engine, market, payload option and M Sport/M Performance brake equipment can select a different rotor even within the F25 chassis.",detail:"Match diameter, nominal thickness, minimum thickness, hat geometry and part number. BMW says standard non-perforated discs are replaced after 2.4 mm total thickness loss; perforated and M discs use a different 1.6-mm rule. Measure at several points away from the outer wear lip with an appropriate micrometer.",values:[{label:"Front rotor diameter",value:"328 mm",note:"12.91 in"},{label:"Nominal thickness",value:"28.0 mm",note:"Ventilated front disc"},{label:"Minimum thickness",value:"26.4 mm",note:"Stamped MIN TH controls"},{label:"Standard-disc replacement rule",value:"Nominal minus 2.4 mm",note:"Not for perforated/M discs"},{label:"Final identification",value:"VIN + BMW EPC",note:"Equipment can change rotor"}],source:bmwX3F25Brakes,sources:[bmwX3F25Brakes,S.bmw],diagram:"wheel"},
  {slug:"nissan/titan/towing-capacity",keyword:"nissan titan towing capacity specs",make:"Nissan",model:"2024 TITAN / TITAN XD",category:"Vehicle Specifications",title:"2024 Nissan Titan Towing Capacity: TITAN vs. TITAN XD",answer:"For 2024, Nissan lists up to 9,290 lb for a TITAN Crew Cab 4x2 and up to 11,050 lb for a TITAN XD Crew Cab 4x4 using a gooseneck hitch. The XD conventional maximum is 10,900 lb.",scope:"These are final-model-year U.S. brochure maximums, not the rating of every truck. King Cab, Crew Cab, 4x2/4x4, TITAN versus XD, hitch type and installed equipment select the correct row; the certification and payload labels on the actual vehicle still control.",detail:"Calculate with the truck loaded for travel. Passengers, bed cargo, accessories and hitch load increase vehicle weight and reduce available towing capacity. Nissan directs owners to keep conventional trailer tongue weight generally between 10 and 15 percent while remaining under every listed tongue, axle, GVWR and GCWR limit.",values:[{label:"TITAN Crew Cab 4x2 maximum",value:"9,290 lb",note:"2024 brochure maximum"},{label:"TITAN King Cab 4x4 maximum",value:"9,210 lb",note:"Configuration-specific"},{label:"TITAN Crew Cab 4x4 maximum",value:"9,130 lb",note:"Configuration-specific"},{label:"TITAN XD conventional maximum",value:"10,900 lb",note:"Crew Cab 4x4"},{label:"TITAN XD gooseneck maximum",value:"11,050 lb",note:"Properly equipped"},{label:"TITAN XD maximum payload",value:"2,360 lb",note:"Door-label payload may be lower"}],source:nissanTitan2024,sources:[nissanTitan2024,nissanTitanManual2024,S.nissan],diagram:"main"},
  {slug:"jeep/compass/tire-pressure",keyword:"jeep compass tire pressure specs",make:"Jeep",model:"2023 Compass",category:"Vehicle Specifications",title:"2023 Jeep Compass Tire Pressure: Read the Correct Placard",answer:"The correct 2023 Jeep Compass tire pressure is the cold value printed on that vehicle's driver-side B-pillar or door-edge Tire and Loading Information placard. Mopar does not publish one universal internet number for every tire package; its manual uses 33 psi only as a TPMS temperature example, not as a blanket specification.",scope:"Covers the U.S.-market 2023 Compass with factory-approved tires. Trim, original tire size, replacement load rating, market and spare-wheel equipment can change what appears on the placard, so a nearby Compass or a generic 35-psi chart is not authoritative for a particular vehicle.",detail:"Cold means the vehicle has been parked for at least three hours or driven less than 1 mile after that rest. Pressure changes by about 1 psi for each 12°F change in ambient temperature, and normal driving raises pressure; do not bleed a warm tire back to the cold target. The tire sidewall shows the tire's maximum permissible pressure, not Jeep's recommended operating pressure. Set all four road tires from the placard with an accurate gauge, check the spare separately if fitted, reinstall valve caps, and allow the TPMS time to update while driving.",values:[{label:"Normal road-tire target",value:"Use vehicle placard",note:"Driver-side B-pillar or rear door edge"},{label:"Cold definition",value:"Parked 3+ hours",note:"Or driven less than 1 mile after resting"},{label:"Temperature effect",value:"About 1 psi per 12°F",note:"7 kPa per 6.5°C"},{label:"33-psi manual example",value:"Example only",note:"Not a universal Compass specification"},{label:"Tire sidewall number",value:"Maximum, not target",note:"Never substitute for placard pressure"}],source:compass2023,sources:[compass2023,S.mopar],reviewed:"2026-08-21",diagram:"wheel"},
  {slug:"subaru/ascent/towing-capacity",keyword:"subaru ascent towing capacity specs",make:"Subaru",model:"2019 Ascent",category:"Vehicle Specifications",title:"2019 Subaru Ascent Towing Capacity: Factory 5,000-lb Maximum",answer:"Subaru introduced the 2019 Ascent with trailer capacity of up to 5,000 lb. That maximum is configuration- and equipment-dependent; it should not be copied onto another model year or treated as the available capacity after loading the cabin.",scope:"This page is anchored to Subaru's U.S. 2019 launch specifications for the 2.4L turbo BOXER/CVT powertrain. The exact owner's manual and vehicle labels still control hitch requirements, trailer-brake rules, tongue load and the rating for a particular trim.",detail:"Subaru lists Trailer Stability Assist, but an electronic aid cannot increase the mechanical rating or compensate for poor loading. Deduct passengers, cargo, accessories and tongue weight from available payload, keep the trailer within its own ratings, and verify the receiver and electrical connection before departure.",values:[{label:"Maximum trailer capacity",value:"5,000 lb",note:"Factory 2019 model maximum"},{label:"Engine",value:"2.4L turbo BOXER",note:"260 hp; 277 lb-ft"},{label:"Transmission",value:"High-torque Lineartronic CVT",note:"Eight-speed manual mode"},{label:"Stability feature",value:"Trailer Stability Assist",note:"Does not raise the rated limit"}],source:subaruAscent2019,diagram:"main"},
  {slug:"hyundai/palisade/oil-capacity",keyword:"hyundai palisade oil capacity specs",make:"Hyundai",model:"2026 Palisade 3.5L",category:"Fluid Capacities",title:"2026 Hyundai Palisade Oil Capacity and Required 0W-20",answer:"Hyundai specifies 6.13 US qt (5.8 L) for a drain-and-refill on the 2026 Palisade's Smartstream 3.5L GDI V6.",scope:"This is the exact U.S. 2026 LX3 Palisade row. Earlier Palisades use a 3.8L V6 with a different service quantity, so the familiar older-generation number must not be carried forward to the redesigned 3.5L vehicle.",detail:"Use SAE 0W-20 full-synthetic oil meeting API SN PLUS/SP or ILSAC GF-6. Refill short of the listed quantity first, start the engine and check for leaks, shut it down on level ground and allow oil to return to the pan before bringing the dipstick to full. A published refill quantity is not permission to overfill.",values:[{label:"Drain-and-refill quantity",value:"6.13 US qt",note:"5.8 L"},{label:"Engine",value:"Smartstream 3.5 GDI",note:"2026 LX3 Palisade"},{label:"Viscosity",value:"SAE 0W-20",note:"Full synthetic"},{label:"Oil quality",value:"API SN PLUS/SP or ILSAC GF-6",note:"Certification required"}],source:hyundaiPalisade2026,diagram:"oil"},
  {slug:"ford/expedition/wheel-torque",keyword:"ford expedition wheel torque specs",make:"Ford",model:"2021 Expedition",category:"Torque Specs",title:"2021 Ford Expedition Wheel Lug Nut Torque",answer:"Ford specifies 150 lb-ft (204 N·m) for the M14 x 1.5 wheel lug nuts on the 2021 Expedition.",scope:"This exact value is from the 2021 U.S. Expedition owner manual for factory wheel hardware. Earlier generations, aftermarket wheels and replacement fasteners with a different seat design require their own instructions.",detail:"Remove dirt, rust and loose corrosion from the hub pilot and mating faces. Keep the specified threads free of dirt and rust, start each nut by hand, and tighten across the wheel in stages with a calibrated wrench. Ford requires retightening to specification within 100 miles (160 km) after tire rotation, flat-tire service or any other wheel removal.",values:[{label:"Wheel lug nut torque",value:"150 lb-ft",note:"204 N·m"},{label:"Thread size",value:"M14 x 1.5",note:"Factory fastener"},{label:"Recheck interval",value:"Within 100 mi",note:"160 km after wheel disturbance"},{label:"Mounting surface",value:"Clean metal-to-metal contact",note:"Remove corrosion and loose particles"}],source:fordExpedition2021,diagram:"wheel"},
  {slug:"chevrolet/suburban/fuel-tank-capacity",keyword:"chevy suburban fuel tank capacity specs",make:"Chevrolet",model:"2025 Suburban",category:"Fluid Capacities",title:"2025 Chevy Suburban Fuel Tank Capacity: 28 Gallons",answer:"Chevrolet lists the 2025 Suburban's fuel-tank capacity at approximately 28 US gal (106 L) in both 2WD and 4WD form.",scope:"This figure is for the U.S.-market 2025 Suburban. It is a nominal tank capacity, not the amount a normal pump visit should always dispense, and it should not be transferred to an older Suburban 1500/2500 or a Tahoe.",detail:"The low-fuel warning appears while usable reserve remains, and fuel can remain in the tank, lines and module. Temperature, pump shutoff behavior and vehicle angle also change the amount accepted. Do not continue forcing fuel in after the nozzle repeatedly clicks off; use the gauge and range estimate as aids rather than attempting to prove nominal capacity at the pump.",values:[{label:"2025 Suburban 2WD",value:"28 US gal",note:"Approximately 106 L"},{label:"2025 Suburban 4WD",value:"28 US gal",note:"Approximately 106 L"},{label:"Capacity type",value:"Nominal tank volume",note:"Not expected refill amount"},{label:"Tahoe comparison",value:"24 US gal",note:"Do not substitute the shorter model's tank figure"}],source:chevroletSuburban2025,diagram:"oil"},
  {slug:"ram/3500/towing-capacity",keyword:"dodge ram 3500 towing capacity chart",make:"Ram",model:"2024 Ram 3500",category:"Vehicle Specifications",title:"2024 Ram 3500 Towing Capacity: 37,090-lb Maximum Explained",answer:"The 2024 Ram 3500 reaches a maximum 37,090-lb trailer rating only in qualifying 4x2, regular-cab, long-bed, dual-rear-wheel configurations with the high-output 6.7L Cummins, Aisin transmission and 4.10 axle.",scope:"This is a configuration maximum from Ram's 2024 SAE J2807 Heavy Duty chart—not a universal rating for every 3500. Gas versus diesel, standard versus high-output Cummins, axle ratio, regular/crew/Mega Cab, bed, 4x2/4x4 and single/dual rear wheels each change the row.",detail:"Maximum payload and maximum trailer weight occur on different configurations and are mutually exclusive in Ram's chart. Confirm the truck's VIN equipment, GVWR, GCWR, axle ratings, payload label and hitch limits; then subtract occupants, cargo, accessories and pin or tongue weight before declaring that a trailer fits.",values:[{label:"Maximum available towing",value:"37,090 lb",note:"HO Cummins qualifying configuration"},{label:"Engine",value:"6.7L HO Cummins",note:"Aisin automatic"},{label:"Axle ratio at maximum",value:"4.10",note:"Configuration-specific"},{label:"Drivetrain/cab at maximum",value:"4x2 Regular Cab",note:"Long bed, dual rear wheels"},{label:"Maximum gas-engine payload row",value:"7,680 lb",note:"Different configuration; not simultaneous max tow"},{label:"Standards basis",value:"SAE J2807",note:"Factory chart still requires exact row"}],source:ramHdTow2024,diagram:"main"},
  {slug:"honda/hr-v/spark-plug-torque",keyword:"honda hr-v spark plug torque specs",make:"Honda",model:"2016–2021 HR-V 1.8L",category:"Ignition Specs",title:"Honda HR-V 1.8L Spark Plug Torque: 18 N-m Service Guide",answer:"The RU-generation Honda HR-V 1.8L spark plugs are tightened to 18 N·m (13 lb-ft) in the covered factory service procedure.",scope:"This applies to the North American 2016–2021 HR-V 1.8L application and the specified gasket-seat plug. The 2023-and-newer 2.0L HR-V, international 1.5L engines and a different plug design require their own service information.",detail:"Work on a cold engine, clear debris from the wells and thread each plug fully by hand before using a torque wrench. Honda's covered procedure calls for a small amount of anti-seize; if a replacement plug manufacturer supplies a different lubricated/dry torque instruction, reconcile that instruction with the exact Honda service data rather than adding lubricant casually.",values:[{label:"Spark-plug torque",value:"18 N·m",note:"13 lb-ft"},{label:"Engine/application",value:"1.8L RU HR-V",note:"North America 2016–2021"},{label:"Installation",value:"Finger-start first",note:"Cold aluminum cylinder head"},{label:"Replacement plug",value:"VIN-approved exact part",note:"Match seat, reach and heat range"},{label:"2023+ HR-V 2.0L",value:"Separate procedure",note:"Do not transfer this value automatically"}],source:hondaHrvIgnition,sources:[hondaHrvIgnition,S.honda],diagram:"spark",engine:true},
  {slug:"bmw/7-series/battery-replacement",keyword:"bmw 7 series battery replacement specs",make:"BMW",model:"BMW 7 Series",category:"Electrical Specifications",title:"BMW 7 Series Battery Replacement: Registration and Coding",answer:"A BMW 7 Series replacement 12-volt battery must match the VIN-defined chemistry, capacity, size and venting, and BMW requires the replacement to be registered with diagnostic equipment.",scope:"This guidance covers modern energy-managed 7 Series vehicles, including applications that may have AGM, auxiliary or 48-volt systems. It intentionally does not publish one universal amp-hour number because E65, F01, G11 and G70 equipment differ materially.",detail:"Registration records battery age/replacement for charging management. If chemistry or rated capacity changes, coding or conversion programming may also be required; registration alone does not make an incorrectly sized battery compatible. Preserve vehicle power only with an approved support procedure and identify every installed battery before disconnecting anything.",values:[{label:"Battery chemistry",value:"Match VIN equipment",note:"Maintenance-free or AGM; never guess"},{label:"Amp-hour rating",value:"Match original/coded class",note:"Example labels are not universal"},{label:"After like-for-like replacement",value:"Register battery",note:"BMW diagnostic service function"},{label:"Changed type or capacity",value:"Coding may be required",note:"Registration is a separate step"},{label:"48V or auxiliary battery",value:"Separate safety procedure",note:"Do not treat as ordinary 12V battery"}],source:bmwBatteryRegistration,sources:[bmwBatteryRegistration,bmwBatteryTestPlan,S.bmw],diagram:"main"},
  {slug:"nissan/frontier/oil-capacity",keyword:"nissan frontier oil capacity specs",make:"Nissan",model:"2024 Frontier 3.8L",category:"Fluid Capacities",title:"2024 Nissan Frontier Oil Capacity: With and Without Filter",answer:"Nissan specifies approximately 5.25 US qt (5.0 L) for a 2024 Frontier oil change with a new filter and 5.0 US qt (4.7 L) when the filter is not changed.",scope:"These figures apply to the U.S.-market 2024 Frontier's 3.8L V6. Older 2.5L four-cylinder and 4.0L V6 trucks use different rows, so the familiar capacity from an earlier generation should not be carried forward.",detail:"Nissan recommends Genuine Nissan 0W-20 SP or an equivalent synthetic SAE 0W-20 meeting API SP and ILSAC GF-6A. The manual calls both quantities approximate because oil temperature and drain time affect the refill. Add less than the listed amount first, run the engine, inspect for leaks, shut it down, wait more than 10 minutes on level ground and use the dipstick to establish the final level.",values:[{label:"Oil and filter change",value:"5.25 US qt",note:"5.0 L; 4-3/8 Imperial qt"},{label:"Oil change, filter retained",value:"5.0 US qt",note:"4.7 L; 4-1/8 Imperial qt"},{label:"Recommended viscosity",value:"SAE 0W-20",note:"Synthetic"},{label:"Required quality",value:"API SP / ILSAC GF-6A",note:"Final level by dipstick"}],source:nissanFrontier2024,diagram:"oil"},
  {slug:"jeep/renegade/tire-size",keyword:"jeep renegade tire size specifications",make:"Jeep",model:"2017 Renegade",category:"Vehicle Specifications",title:"2017 Jeep Renegade Tire Sizes: 16-, 17- and 18-Inch Chart",answer:"The 2017 Jeep Renegade guide lists 215/65R16, 215/60R17, 215/65R17 for Trailhawk and 225/55R18 factory tire applications.",scope:"This chart is anchored to the North American 2017 Renegade. A tire-size string alone does not establish pressure, load capacity, speed rating or wheel compatibility; confirm the tire-and-loading label and the vehicle's original equipment before buying replacements.",detail:"The guide permits low-profile 7-mm traction devices on the front axle only with 215/65R16 or 215/60R17 tires. It marks 215/65R17 Trailhawk and 225/55R18 applications as not chainable. Do not mix tire sizes or constructions front to rear, and do not assume that another 17-inch Renegade package has the same clearance.",values:[{label:"16-inch application",value:"215/65R16",note:"7-mm traction devices: front only"},{label:"Standard 17-inch application",value:"215/60R17",note:"7-mm traction devices: front only"},{label:"Trailhawk 17-inch application",value:"215/65R17",note:"Not chainable in factory guide"},{label:"18-inch application",value:"225/55R18",note:"Not chainable in factory guide"},{label:"Traction-device speed limit",value:"30 mph max",note:"48 km/h; retighten after 0.5 mi / 0.8 km"}],source:jeepRenegade2017Tires,diagram:"wheel"},
  {slug:"subaru/brz/wheel-torque",keyword:"subaru brz wheel torque specs",make:"Subaru",model:"2013 Subaru BRZ",category:"Torque Specs",title:"2013 Subaru BRZ Wheel Nut Torque: 120 N-m",answer:"Subaru specifies 120 N·m, approximately 89 lb-ft, for the wheel nuts on the covered 2013 BRZ with factory wheels and original-style hardware.",scope:"The exact value is anchored to the 2013 BRZ factory service specification. Later BRZ generations should be checked in their model-year information, while aftermarket wheels, extended studs and changed nut-seat geometry follow the wheel or hardware maker's instructions.",detail:"Clean rust and debris from the hub and wheel mounting faces, keep the studs and nut seats dry unless Subaru explicitly directs otherwise, hand-start every nut and tighten in several opposite-side passes. Finish all five positions at the same 120-N·m setting with a calibrated torque wrench.",values:[{label:"Wheel nut torque",value:"120 N·m",note:"Approximately 89 lb-ft"},{label:"Tightening pattern",value:"Five-lug star",note:"Opposite-side staged passes"},{label:"Threads and seats",value:"Clean and dry",note:"Do not alter friction casually"},{label:"Aftermarket wheels or studs",value:"Manufacturer instructions",note:"Seat and hardware may change"}],source:subaruBrz2013Wheel,diagram:"wheel"},
  {slug:"hyundai/genesis/horsepower-by-year",keyword:"hyundai genesis horsepower specs by year",make:"Hyundai",model:"2015 Genesis Sedan",category:"Engine Specifications",title:"2015 Hyundai Genesis Horsepower: 3.8 V6 vs. 5.0 V8",answer:"The U.S.-market 2015 Hyundai Genesis sedan was rated at 311 hp with the 3.8L V6 and 420 hp with the 5.0L V8.",scope:"This chart is deliberately limited to the redesigned 2015 Hyundai-branded Genesis sedan. It does not describe the Genesis Coupe, the earlier 2013–2014 sedan, or later vehicles sold under the standalone Genesis marque.",detail:"Hyundai rated the direct-injected 3.8L Lambda V6 at 311 hp at 6,000 rpm and 293 lb-ft at 5,000 rpm. The direct-injected 5.0L Tau V8 produced 420 hp at 6,000 rpm and 383 lb-ft at 5,000 rpm. Horsepower numbers should be compared at the same model year and using factory ratings, not chassis-dyno results or altered-fuel claims.",values:[{label:"2015 Genesis 3.8",value:"311 hp @ 6,000 rpm",note:"293 lb-ft @ 5,000 rpm"},{label:"2015 Genesis 5.0",value:"420 hp @ 6,000 rpm",note:"383 lb-ft @ 5,000 rpm"},{label:"Fuel note",value:"Factory SAE output",note:"Hyundai notes regular fuel can slightly reduce peak power"},{label:"Genesis Coupe",value:"Separate model",note:"Do not merge coupe engine ratings"}],source:hyundaiGenesis2015,diagram:"main",engine:true},
  {slug:"ford/maverick/towing-capacity",keyword:"ford maverick towing capacity chart",make:"Ford",model:"2022 Maverick",category:"Vehicle Specifications",title:"2022 Ford Maverick Towing Capacity: 2,000 vs. 4,000 lb",answer:"The 2022 Ford Maverick has a 2,000-lb standard maximum towing rating. The 2.0L EcoBoost can reach 4,000 lb when equipped with the available 4K Tow Package.",scope:"These are U.S. 2022 model-year maximum ratings from Ford's technical specifications. A 2.0L engine by itself does not prove the truck has the 4K package, and the standard 2.5L hybrid row remains 2,000 lb.",detail:"Confirm the powertrain and factory tow package from the VIN/build data, then use the certification label to calculate remaining payload. Trailer tongue weight, passengers, bed cargo and accessories all consume payload, so the advertised maximum does not mean every 4K-equipped truck can carry every combination of people and cargo while towing 4,000 lb.",values:[{label:"2.5L hybrid FWD",value:"2,000 lb max",note:"Standard 2022 rating"},{label:"2.0L EcoBoost",value:"2,000 lb standard",note:"FWD or AWD without qualifying 4K setup"},{label:"2.0L + 4K Tow Package",value:"4,000 lb max",note:"Factory package required"},{label:"Maximum payload",value:"Up to 1,500 lb",note:"Actual door-label payload varies"}],source:fordMaverick2022,diagram:"main"},
  {slug:"chevrolet/camaro/horsepower-by-year",keyword:"chevy camaro horsepower specs by year",make:"Chevrolet",model:"2024 Camaro",category:"Engine Specifications",title:"2024 Chevy Camaro Horsepower: V6, LT1/SS and ZL1",answer:"The final 2024 Camaro lineup spans 335 hp for the 3.6L V6, 455 hp for the naturally aspirated 6.2L LT1 V8 in LT1/SS models and 650 hp for the ZL1's supercharged 6.2L LT4.",scope:"This table is deliberately limited to the U.S.-market 2024 sixth-generation Camaro. It does not carry historical gross ratings into a modern comparison, and it does not confuse the LT1 trim name with the LT1 engine used by both LT1 and SS models.",detail:"Compare engine output, not trim appearance. Transmission choice does not change the cited engine horsepower for these 2024 rows, although acceleration and driveline behavior differ. Collector Edition equipment is primarily appearance/content and does not create a separate higher-output engine rating.",values:[{label:"2024 LT 3.6L V6",value:"335 hp",note:"Naturally aspirated"},{label:"2024 LT1 / SS 6.2L LT1",value:"455 hp",note:"Naturally aspirated V8"},{label:"2024 ZL1 6.2L LT4",value:"650 hp",note:"Supercharged V8"},{label:"Model-year status",value:"Final Camaro year",note:"Sixth-generation production ended"},{label:"Historic horsepower",value:"Separate rating context",note:"Gross and SAE net are not interchangeable"}],source:camaroLt2024,sources:[camaroLt2024,camaroZl12024,S.gm],diagram:"main",engine:true},
  {slug:"toyota/crown/oil-capacity",keyword:"toyota crown oil capacity specs",make:"Toyota",model:"2024 Crown",category:"Fluid Capacities",title:"2024 Toyota Crown Oil Capacity: 2.5L vs. Hybrid MAX",answer:"For the 2024 North American Crown, the 2.5L A25A-FXS hybrid uses 4.5 US qt (4.3 L) with filter, while the 2.4L turbo T24A-FTS Hybrid MAX uses 5.6 US qt (5.3 L) with filter.",scope:"These figures apply to the 2024 U.S./Canada Crown crossover sedan and must be matched by engine code. They do not cover the Crown Signia, older imported Crown generations, Japanese-market body styles or another Toyota that happens to use a related engine.",detail:"The two current powertrains also use different oil specifications: the naturally aspirated 2.5L hybrid row calls for JASO GLV-1 SAE 0W-8, while the 2.4L turbo row calls for the model-year Toyota-approved grade shown in its manual. Toyota treats both capacities as drain-and-refill references. Warm the engine, shut the hybrid system off, wait about five minutes on level ground, add below the total first, then finish at the dipstick instead of forcing the whole bottle count into the crankcase.",values:[{label:"2024 XLE/Limited 2.5L A25A-FXS",value:"4.5 US qt",note:"4.3 L with filter"},{label:"2024 Platinum 2.4L T24A-FTS",value:"5.6 US qt",note:"5.3 L with filter"},{label:"2.5L without filter",value:"4.2 US qt",note:"4.0 L; normal service should replace filter"},{label:"2.4L without filter",value:"5.3 US qt",note:"5.0 L"},{label:"2.5L oil viscosity",value:"SAE 0W-8",note:"JASO GLV-1 in cited manual"}],source:toyotaCrown2024,sources:[toyotaCrown2024,S.toyota],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"dodge/durango/horsepower",keyword:"dodge durango horsepower specs chart",make:"Dodge",model:"2023 Durango",category:"Engine Specifications",title:"2023 Dodge Durango Horsepower Chart by Engine and Trim",answer:"For 2023, Dodge rates the Durango at up to 295 hp with the 3.6L V6, 360 hp with the 5.7L HEMI, 475 hp with the 6.4L SRT 392 and 710 hp with the supercharged 6.2L SRT Hellcat.",scope:"This chart is specific to the U.S.-market 2023 Durango lineup. Similar trim names in other years can have different availability, and the Hellcat figure must not be assigned to an R/T or SRT 392.",detail:"Factory torque is equally important: the 3.6L is rated at up to 260 lb-ft, the 5.7L at 390 lb-ft, the 6.4L at 470 lb-ft and the Hellcat at 645 lb-ft. Horsepower alone does not establish towing capacity; engine cooling, axle ratio, brakes, hitch equipment, GCWR and the vehicle's payload label remain separate limits.",values:[{label:"3.6L Pentastar V6",value:"Up to 295 hp",note:"260 lb-ft; SXT/GT/Citadel applications"},{label:"5.7L HEMI V8",value:"360 hp",note:"390 lb-ft; R/T and optional Citadel"},{label:"6.4L SRT 392 V8",value:"475 hp",note:"470 lb-ft"},{label:"6.2L supercharged Hellcat",value:"710 hp",note:"645 lb-ft"}],source:dodgeDurango2023,diagram:"main",engine:true},
  {slug:"honda/ridgeline/towing-capacity",keyword:"honda ridgeline towing capacity specs",make:"Honda",model:"2024 Ridgeline",category:"Vehicle Specifications",title:"2024 Honda Ridgeline Towing Capacity and Tongue-Weight Limit",answer:"Honda lists a 5,000-lb maximum towing capacity and a 600-lb maximum tongue weight for the 2024 Ridgeline with the described Class III towing equipment.",scope:"These are 2024 U.S. brochure figures. They do not automatically apply to an earlier front-wheel-drive Ridgeline, a missing towing component, an overloaded truck or a trailer whose own rating is lower.",detail:"Tongue weight is part of the truck's load, so passengers, cargo, bed accessories and hitch load must fit the payload shown for the actual vehicle. Confirm the receiver, ball mount, ball, safety chains, seven-pin connection and any brake-controller requirement. Keep both gross trailer weight and tongue weight within their separate limits.",values:[{label:"Maximum towing capacity",value:"5,000 lb",note:"2024 Honda brochure"},{label:"Maximum tongue weight",value:"600 lb",note:"Separate hard limit"},{label:"Receiver class",value:"Class III",note:"Honda towing equipment"},{label:"Electrical connection",value:"Verify trailer connector and brakes",note:"Trailer-specific requirements still apply"}],source:hondaRidgeline2024,diagram:"main"},
  {slug:"bmw/m5/horsepower-by-year",keyword:"bmw m5 horsepower specs by year",make:"BMW",model:"2025 M5 G90",category:"Engine Specifications",title:"2025 BMW M5 Horsepower: 717-hp G90 Hybrid Explained",answer:"BMW rates the 2025 G90 M5 sedan at 717 hp and 738 lb-ft of combined system output from its M Hybrid powertrain.",scope:"These are U.S.-market G90 M5 system ratings, not the combustion engine's standalone output and not a carryover F90 Competition or CS figure. The plug-in hybrid combines a 4.4L twin-turbo V8 with an electric motor through an eight-speed automatic and M xDrive.",detail:"BMW lists maximum power from 5,600–6,500 rpm and peak system torque from 1,800–5,400 rpm. The battery need not show usable electric range for maximum power under normal operating conditions because the system preserves and replenishes an energy buffer, but temperature, drive mode and protection limits can still affect delivered performance.",values:[{label:"2025 M5 system power",value:"717 hp",note:"5,600–6,500 rpm"},{label:"System torque",value:"738 lb-ft",note:"1,800–5,400 rpm"},{label:"Combustion engine",value:"4.4L twin-turbo V8",note:"M Hybrid system component"},{label:"Transmission",value:"8-speed automatic",note:"M xDrive all-wheel drive"},{label:"Curb weight",value:"5,390 lb",note:"BMW U.S. technical data"}],source:bmwM5Current,diagram:"main",engine:true},
  {slug:"nissan/murano/spark-plug-gap",keyword:"nissan murano spark plug gap specs",make:"Nissan",model:"2011 Nissan Murano 3.5L VQ35DE",category:"Ignition Specs",title:"2011 Nissan Murano Spark Plug Gap and Service Limit",answer:"For the covered 2011 Nissan Murano VQ35DE, the standard spark-plug gap is 1.1 mm (0.043 in). Nissan lists 1.4 mm (0.055 in) as the wear limit; a fine-wire plug at or beyond that limit should be replaced rather than forced back to size.",scope:"The figures apply to the documented 2011 Murano 3.5L VQ35DE. Earlier and later Murano engines, hybrids, different markets and non-approved plug designs require the plug number and service information for that exact application.",detail:"Nissan's VQ35DE procedure treats the specified long-life plug as the controlling part and says gap adjustment is not required between replacement intervals. Inspect for a cracked insulator, rounded electrodes, oil or fuel fouling and replace with the approved reach, seat and heat range instead of selecting a plug by gap alone.",values:[{label:"Standard new-plug gap",value:"1.1 mm",note:"0.043 in"},{label:"Service limit",value:"1.4 mm",note:"0.055 in; replace worn plug"},{label:"Between service intervals",value:"No regapping required",note:"Inspect and replace if out of limit"},{label:"Replacement selection",value:"Approved exact plug",note:"Match reach, seat and heat range"}],source:nissanMurano2011Spark,diagram:"spark",engine:true},
  {slug:"jeep/patriot/wheel-torque",keyword:"jeep patriot wheel torque specs",make:"Jeep",model:"2017 Patriot",category:"Torque Specs",title:"2017 Jeep Patriot Lug Nut Torque and Tightening Pattern",answer:"The 2017 Jeep Patriot user guide specifies 100 ft-lb (135 N·m) for the wheel nuts/bolts.",scope:"This exact row applies to a 2017 Patriot using the factory M12 x 1.5 fasteners and their original conical-seat wheel interface. Aftermarket wheels can specify different hardware or a different procedure.",detail:"Inspect the hub and wheel mounting faces and remove loose corrosion. Keep the threads free of dirt and oil, start every nut by hand, lower the vehicle enough to prevent rotation, then tighten in a star pattern until every nut has been torqued twice. Mopar calls for another torque check after 25 miles (40 km).",values:[{label:"Wheel fastener torque",value:"100 ft-lb",note:"135 N·m; 2017 Mopar guide"},{label:"Thread size",value:"M12 x 1.5",note:"Factory hardware"},{label:"Socket size",value:"19 mm",note:"Use a six-point socket"},{label:"Post-service recheck",value:"After 25 mi",note:"40 km"}],source:jeepPatriot2017,diagram:"wheel"},
  {slug:"subaru/wrx/oil-capacity",keyword:"subaru wrx oil capacity specifications",make:"Subaru",model:"2018 WRX / WRX STI",category:"Fluid Capacities",title:"2018 Subaru WRX Oil Capacity: WRX vs. WRX STI",answer:"Subaru specifies 5.4 US qt (5.1 L) for a 2018 WRX oil-and-filter change and 4.5 US qt (4.3 L) for the 2018 WRX STI. The two turbo models do not share one refill quantity.",scope:"These figures are limited to the 2018 U.S. WRX with the FA20DIT and WRX STI with the EJ257. They should not be transferred to the later FA24 WRX, an earlier EJ-series car or another market without checking its manual.",detail:"Subaru calls for synthetic SAE 5W-30 meeting API SN with Resource Conserving wording or ILSAC GF-5 in this guide. Add less than the stated service quantity first, run the engine and inspect for leakage, wait on level ground for drain-back, and finish at the full mark. The STI's lower published quantity is not a typo and the WRX figure is not a safe substitute.",values:[{label:"2018 WRX oil and filter",value:"5.4 US qt",note:"5.1 L; 4.5 Imperial qt"},{label:"2018 WRX STI oil and filter",value:"4.5 US qt",note:"4.3 L; 3.8 Imperial qt"},{label:"Specified viscosity",value:"SAE 5W-30 synthetic",note:"Both guide rows"},{label:"Oil quality",value:"API SN RC or ILSAC GF-5",note:"Final level by dipstick"}],source:subaruWrx2018,diagram:"oil"},
  {slug:"hyundai/elantra-n/horsepower",keyword:"hyundai elantra n horsepower specs",make:"Hyundai",model:"2022 Elantra N",category:"Engine Specifications",title:"2022 Hyundai Elantra N Horsepower and N Grin Shift Output",answer:"Hyundai rates the 2022 Elantra N's 2.0L turbo engine at 276 hp and 289 lb-ft. On the eight-speed DCT model, N Grin Shift briefly raises output to 286 hp.",scope:"This factory rating applies to the North American 2022 Elantra N. The Elantra N Line is a different trim and powertrain; 286 hp is a temporary DCT overboost figure, not the engine's continuous rating and not a manual-transmission feature.",detail:"Maximum standard power is delivered from 5,500–6,000 rpm, while the 289 lb-ft torque plateau is listed from 2,100–4,700 rpm. Pressing the NGS control on an eligible DCT car increases turbo boost and transmission response for up to 20 seconds. Conditions and safeguards in the owner's manual still apply.",values:[{label:"Standard maximum output",value:"276 hp",note:"5,500–6,000 rpm"},{label:"Peak torque",value:"289 lb-ft",note:"2,100–4,700 rpm"},{label:"N Grin Shift output",value:"286 hp",note:"Up to 20 seconds; DCT only"},{label:"Six-speed manual",value:"276 hp",note:"No DCT NGS overboost function"}],source:hyundaiElantraN2022,diagram:"main",engine:true},
  {slug:"ford/transit/oil-capacity",keyword:"ford transit oil capacity chart",make:"Ford",model:"2022 Transit",category:"Fluid Capacities",title:"2022 Ford Transit Oil Capacity: Duratec vs. EcoBoost",answer:"Ford lists 6.0 US qt (5.7 L) including the filter for both gasoline engines in the 2022 U.S. full-size Transit: the naturally aspirated 3.5L Duratec and the 3.5L EcoBoost.",scope:"This exact chart is limited to the 2022 U.S./Canada full-size Transit. It does not apply to Transit Connect, E-Series, European-market 2.0L EcoBlue or 2.2L/3.2L diesels, another model year, or a replacement oil pan. Identify the engine and market even though both cited gasoline rows happen to share capacity.",detail:"Shared capacity does not mean shared oil identity. The 2022 Ford rows call for SAE 5W-30 meeting WSS-M2C961-A1, with SAE 0W-30 meeting WSS-M2C963-A1 identified for extremely cold climates. Ford notes that approximately 1.0 qt moves the dipstick from minimum to nominal and warns against filling above maximum. After replacing the filter, add less than six quarts, run the engine, inspect for leaks, wait for drain-back on level ground and approach the full mark gradually.",values:[{label:"2022 3.5L Duratec with filter",value:"6.0 US qt",note:"5.7 L"},{label:"2022 3.5L EcoBoost with filter",value:"6.0 US qt",note:"5.7 L"},{label:"Specified oil",value:"SAE 5W-30",note:"Ford WSS-M2C961-A1"},{label:"Extreme-cold alternative",value:"SAE 0W-30",note:"WSS-M2C963-A1 at -22°F/-30°C or below"},{label:"Dipstick MIN-to-nominal",value:"About 1.0 US qt",note:"0.9 L in Ford manual"}],source:fordTransit2022,sources:[fordTransit2022,S.ford],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"chevrolet/blazer/towing-capacity",keyword:"chevy blazer towing capacity specs",make:"Chevrolet",model:"2023 Blazer",category:"Vehicle Specifications",title:"2023 Chevy Blazer Towing Capacity: Factory 4,500-lb Maximum",answer:"The 2023 Chevrolet Trailering Guide lists a maximum trailer-weight rating of 4,500 lb for a properly equipped Blazer. That is a model maximum, not a promise that every Blazer can tow 4,500 lb.",scope:"This page covers the modern U.S.-market 2023 Blazer crossover, not the classic K5 or Trailblazer. Use the actual vehicle's engine, drivetrain, trailering equipment, payload label and owner information to establish its usable limit.",detail:"Start with the factory rating, then account for passengers, cargo, accessories and hitch load. Trailer tongue weight counts against available vehicle payload. Confirm an approved hitch, wiring, cooling provisions and any trailer-brake requirement before towing; never infer the maximum from appearance or engine displacement alone.",values:[{label:"2023 Blazer model maximum",value:"4,500 lb",note:"When properly equipped"},{label:"Rating type",value:"Maximum trailer weight",note:"Not payload or GCWR"},{label:"Payload deduction",value:"People + cargo + tongue weight",note:"All consume available vehicle capacity"},{label:"Final check",value:"Vehicle labels and owner guide",note:"Configuration-specific limits control"}],source:chevroletTrailering2023,diagram:"main"},
  {slug:"toyota/prius/tire-pressure",keyword:"toyota prius tire pressure specifications",make:"Toyota",model:"2020 Prius",category:"Vehicle Specifications",title:"2020 Toyota Prius Tire Pressure: 15- vs. 17-Inch Tires",answer:"For a 2020 Prius, the factory cold-pressure rows are 36 psi front and 35 psi rear with 195/65R15 tires, or 33 psi front and 32 psi rear with 215/45R17 tires.",scope:"These values apply to the covered U.S.-market 2020 Prius factory tire packages. Prius Prime, Prius c, Prius v, another generation, a replacement-size tire or a vehicle with a different tire-and-loading label requires its own specification.",detail:"Set pressure before driving, when the tires are cold, and use the driver's-door tire-and-loading label as the final authority. The molded pressure on the tire sidewall is a maximum-load reference for the tire—not Toyota's normal operating target. Temperature changes can move the reading even when no puncture is present.",values:[{label:"195/65R15 front",value:"36 psi cold",note:"250 kPa"},{label:"195/65R15 rear",value:"35 psi cold",note:"240 kPa"},{label:"215/45R17 front",value:"33 psi cold",note:"230 kPa"},{label:"215/45R17 rear",value:"32 psi cold",note:"220 kPa"},{label:"Wheel-nut torque",value:"76 lb-ft",note:"103 N·m; separate from tire pressure"}],source:toyotaPrius2020,sources:[toyotaPrius2020,S.toyota],diagram:"wheel"},
  {slug:"ram/1500/spark-plug-gap",keyword:"dodge ram 1500 spark plug gap specs",make:"Ram",model:"2011 1500",category:"Ignition Specs",title:"2011 Ram 1500 Spark Plug Gap Specs by Engine",answer:"For the 2011 Ram 1500, Mopar lists 0.043 in (1.09 mm) for both the 3.7L V6 and 5.7L HEMI. The 4.7L V8 is different: its upper plugs are 0.039 in (0.99 mm) and its lower plugs are 0.051 in (1.30 mm).",scope:"These values are specific to the 2011 Ram 1500 engine and plug rows in the factory guide. They are not a universal specification for later 3.6L Pentastar trucks, later 5.7L plug revisions, or any Cummins diesel.",detail:"Match the engine and the listed replacement plug before measuring. The 5.7L and 4.7L use two plugs per cylinder; on the 4.7L, upper and lower positions intentionally use different plugs and gaps. A fine-wire plug with a damaged electrode should be replaced, not aggressively bent to a target.",values:[{label:"3.7L V6",value:"0.043 in",note:"1.09 mm; ZFR6F-11G"},{label:"5.7L HEMI",value:"0.043 in",note:"1.09 mm; LZFR5C-11"},{label:"4.7L upper bank",value:"0.039 in",note:"0.99 mm; FR8TE2"},{label:"4.7L lower bank",value:"0.051 in",note:"1.30 mm; FR8T1332"}],source:ram1500Guide2011,diagram:"spark",engine:true},
  {slug:"honda/civic/brake-rotor-torque",keyword:"honda civic brake rotor torque specs",make:"Honda",model:"2012 Civic 1.8L",category:"Brake Specifications",title:"2012 Honda Civic Front Brake Torque Specs: Caliper and Rotor",answer:"For the covered 2012 Civic 1.8L front brake, the caliper bracket bolts use 108 N·m (80 lb-ft), caliper bolts 34 N·m (25 lb-ft), hose banjo bolt 35 N·m (26 lb-ft) with new washers and wheel nuts 108 N·m (80 lb-ft).",scope:"These values apply to the cited ninth-generation 2012 Civic 1.8L front-disc procedure. Si, natural-gas, coupe/sedan brake variations, rear drum/disc hardware and later generations require their own rows.",detail:"The rotor itself slides over the hub; it is not secured by the 108-N·m bracket value. Clean the hub and rotor mating faces, support the caliper without loading the hose, keep friction surfaces free of grease and use the service procedure's wheel-nut clamping method when measuring rotor runout.",values:[{label:"Front caliper bracket bolts",value:"108 N·m",note:"80 lb-ft"},{label:"Front caliper bolts",value:"34 N·m",note:"25 lb-ft; exact branch required"},{label:"Front hose banjo bolt",value:"35 N·m",note:"26 lb-ft; use new sealing washers"},{label:"Wheel nuts",value:"108 N·m",note:"80 lb-ft"},{label:"Rotor installation",value:"Clean hub; check runout",note:"No generic bracket torque on rotor"}],source:hondaCivic2012Brakes,sources:[hondaCivic2012Brakes,hondaCivic2012Torque,S.honda],diagram:"wheel"},
  {slug:"bmw/4-series/wheel-torque",keyword:"bmw 4 series wheel torque specs",make:"BMW",model:"4 Series F32/F36",category:"Torque Specs",title:"BMW 4 Series Wheel Bolt Torque: 140 N-m for F32/F36",answer:"BMW F32/F36 4 Series factory wheel bolts use 140 N·m (103 lb-ft) for the covered standard-wheel application.",scope:"The exact row is anchored to the F30/F32 chassis family and factory-style wheel bolts. Confirm the VIN-specific BMW information for G22/G23/G26 cars, M4 applications, accessory wheels, spacers, stud conversions and any non-BMW hardware rather than extending this figure automatically.",detail:"Clean the bolts and inspect their threads and tapered seats, remove rust or debris that prevents the wheel from sitting flat and keep the fasteners dry. Hand-start all five bolts, snug them in a crosswise pattern and perform the final pass with a calibrated torque wrench—never an impact wrench.",values:[{label:"F32/F36 wheel-bolt torque",value:"140 N·m",note:"103 lb-ft"},{label:"Tightening pattern",value:"Five-bolt crosswise",note:"Use progressive passes"},{label:"Wheel-bolt threads",value:"Clean and dry",note:"Do not oil"},{label:"M4 / accessory / aftermarket setup",value:"Separate instructions",note:"Verify wheel and hardware"}],source:bmw4SeriesWheel,sources:[bmw4SeriesWheel,S.bmw],diagram:"wheel"},
  {slug:"nissan/armada/towing-capacity",keyword:"nissan armada towing capacity chart",make:"Nissan",model:"2024 Armada",category:"Vehicle Specifications",title:"2024 Nissan Armada Towing Capacity and Tongue Weight",answer:"Nissan rates the properly equipped 2024 Armada to tow up to 8,500 lb, with a published maximum tongue-weight capacity of 850 lb.",scope:"These are 2024 U.S.-market model maximums, not automatic ratings for every load combination. The vehicle certification label, payload label, receiver, ball mount, trailer brakes, cargo, passenger load and the exact owner's/towing guide must all permit the planned setup. Earlier Armadas and the redesigned 2025 twin-turbo model require their own publications.",detail:"Tongue weight is part of the Armada's carried load. Subtract passengers, luggage, accessories and tongue weight from the door-label payload allowance; then verify that actual trailer weight, GCWR, front and rear GAWR, receiver rating and tire limits are all respected. Weigh the loaded combination rather than relying on an empty-trailer brochure figure. Keep approximately the guide-recommended share of trailer weight on the hitch, use trailer brakes and weight-distributing equipment where Nissan requires them, and never raise a limit by installing a stronger aftermarket hitch.",values:[{label:"2024 maximum trailer weight",value:"8,500 lb",note:"Properly equipped model maximum"},{label:"Maximum tongue-weight capacity",value:"850 lb",note:"Counts against available payload"},{label:"Payload allowance",value:"Door-label specific",note:"Passengers + cargo + tongue weight"},{label:"Loaded trailer weight",value:"Scale-verified",note:"Trailer, fluids, gear and accessories"},{label:"Controlling limits",value:"GVWR / GAWR / GCWR",note:"None may be exceeded"}],source:nissanArmada2024,sources:[nissanArmada2024,nissanTowing2024,S.nissan],reviewed:"2026-08-21",diagram:"main"},
  {slug:"jeep/grand-wagoneer/towing-capacity",keyword:"jeep grand wagoneer towing specs",make:"Jeep",model:"2025 Grand Wagoneer L",category:"Vehicle Specifications",title:"2025 Jeep Grand Wagoneer L Towing Capacity: 9,450-lb Maximum",answer:"The 2025 Jeep Grand Wagoneer L is rated to tow up to 9,450 lb (4,286 kg) in the Stellantis Canada fact sheet. This is the long-wheelbase model's properly equipped maximum, not a universal rating for every Wagoneer-family SUV.",scope:"This page is deliberately limited to the 2025 Grand Wagoneer L specification published for Canada. Standard-wheelbase Grand Wagoneer, regular Wagoneer, another year or a U.S.-market configuration must be checked in its own towing chart.",detail:"The Heavy-Duty Trailer Tow Package and exact configuration matter. Verify the certification label, payload, GCWR, receiver rating, axle and cooling equipment on the vehicle. Occupants, luggage, accessories and tongue weight can make payload the limiting number before the advertised trailer maximum is reached.",values:[{label:"Maximum trailer weight",value:"9,450 lb",note:"2025 Grand Wagoneer L"},{label:"Metric rating",value:"4,286 kg",note:"Factory published conversion"},{label:"Body",value:"Long wheelbase",note:"Do not transfer to standard-wheelbase model"},{label:"Required check",value:"Equipment + payload + GCWR",note:"All limits must be satisfied"}],source:grandWagoneerL2025,diagram:"main"},
  {slug:"hyundai/sonata/spark-plug-gap",keyword:"hyundai sonata spark plug gap specs",make:"Hyundai",model:"Sonata LF 2.0 Turbo",category:"Ignition Specs",title:"Hyundai Sonata LF 2.0T Spark Plug Gap: 0.7–0.8 mm",answer:"The covered Sonata LF turbo service branch specifies a spark-plug gap of 0.7–0.8 mm (0.0275–0.0314 in).",scope:"This narrow gap is for the LF-generation turbo application represented by the cited service procedure. Do not apply it to the 2.4L GDI, 2.0L hybrid, later Smartstream engines or a different approved plug number; naturally aspirated Sonata applications commonly use a wider separate gap.",detail:"Select the plug by exact Hyundai part/application, not gap alone. Fine-wire electrodes can be damaged by a coin-style tool or by levering against the center electrode. Measure only when the service procedure calls for it and replace a damaged or incorrectly supplied plug instead of forcing it into range.",values:[{label:"Covered LF turbo gap",value:"0.7–0.8 mm",note:"0.0275–0.0314 in"},{label:"Engine branch",value:"2.0T / turbo-specific",note:"Confirm engine code and VIN"},{label:"2.4L GDI",value:"Separate wider specification",note:"Do not use turbo gap"},{label:"Plug selection",value:"Approved exact part",note:"Gap alone is insufficient"},{label:"Fine-wire adjustment",value:"Avoid aggressive bending",note:"Replace damaged plugs"}],source:hyundaiSonataLfSpark,sources:[hyundaiSonataLfSpark,S.hyundai],diagram:"spark",engine:true},
  {slug:"ford/bronco/wheel-torque",keyword:"ford bronco wheel torque specifications",make:"Ford",model:"2022 Bronco",category:"Torque Specs",title:"2022 Ford Bronco Wheel Nut Torque: 100 lb-ft",answer:"Ford specifies 100 lb-ft (135 N·m) for the M12 x 1.5 wheel nuts on the 2022 full-size Bronco.",scope:"This is the factory specification for the 2022 Bronco, not the Bronco Sport and not a classic Bronco. Accessory beadlock-capable wheel ring hardware is a separate component and must not be assigned the wheel-nut value.",detail:"Remove dirt, rust and loose corrosion from the wheel pilot bore and both mounting faces. Use replacement fasteners with the correct seat, start them by hand and tighten across the wheel in stages with a calibrated wrench. Ford requires the wheel nuts to be retightened to specification within 100 miles (160 km) after a wheel disturbance such as rotation or removal.",values:[{label:"Wheel nut torque",value:"100 lb-ft",note:"135 N·m; 2022 Ford manual"},{label:"Thread size",value:"M12 x 1.5",note:"Factory wheel nuts"},{label:"Recheck interval",value:"Within 100 mi",note:"160 km after wheel disturbance"},{label:"Bronco Sport",value:"Separate manual",note:"Do not transfer this row"}],source:fordBronco2022,diagram:"wheel"},
  {slug:"chevrolet/corvette/horsepower-by-year",keyword:"chevy corvette horsepower specs by year",make:"Chevrolet",model:"2025 Corvette ZR1",category:"Engine Specifications",title:"2025 Corvette ZR1 Horsepower: 1,064-hp LT7 Specifications",answer:"Chevrolet rates the 2025 Corvette ZR1's 5.5L twin-turbo LT7 at 1,064 hp at 7,000 rpm and 828 lb-ft at 6,000 rpm under SAE guidelines.",scope:"This exact specification applies to the 2025 C8 ZR1 coupe and convertible. It is engine output, unlike a hybrid combined-system figure, and it must not be transferred to the naturally aspirated Z06 LT6, Stingray LT2, E-Ray or the later ZR1X hybrid.",detail:"The LT7 uses a flat-plane crank, dual overhead cams, twin turbochargers, port plus direct injection and dry-sump lubrication. The familiar Z06 LT6 shares displacement and basic architecture but is naturally aspirated and rated separately; the engine code, forced-induction system and firing order are not interchangeable service details.",values:[{label:"2025 ZR1 horsepower",value:"1,064 hp",note:"At 7,000 rpm; SAE"},{label:"Peak torque",value:"828 lb-ft",note:"At 6,000 rpm"},{label:"Engine",value:"LT7 5.5L twin-turbo V8",note:"Flat-plane crank, DOHC"},{label:"Firing order",value:"1-4-3-8-7-6-5-2",note:"LT7 factory specification"},{label:"Oil system",value:"Seven-stage dry sump",note:"8-qt published capacity"},{label:"Z06 comparison",value:"670 hp LT6",note:"Naturally aspirated separate engine"}],source:corvetteZr12025,sources:[corvetteZr12025,S.gm],diagram:"main",engine:true},
  {slug:"toyota/sienna/oil-capacity",keyword:"toyota sienna oil capacity specs",make:"Toyota",model:"Sienna",category:"Fluid Capacities",title:"Toyota Sienna Oil Capacity by Engine and Towing Package",answer:"Toyota's 2020 Sienna 3.5L lists 5.8 US qt (5.5 L) with filter when equipped with the towing package and 5.7 US qt (5.4 L) without it. The 2021-and-newer Sienna changed to a 2.5L hybrid and uses a separate, lower-capacity row that must not be filled from the V6 chart.",scope:"The exact V6 figures below come from the 2020 North American Sienna manual. The current hybrid row is anchored to the 2024 Sienna Hybrid manual. Earlier 3.0L/3.3L vans, older 2GR-FE years, regional models and another model year require their matching manual rather than a generation-wide guess.",detail:"Toyota changed both engine family and powertrain architecture for 2021. On the 2020 V6, the towing-package distinction changes the filter refill by 0.1 qt; without-filter capacity is 5.6 qt. On the fourth-generation A25A-FXS hybrid, the filter-change reference is 4.5 qt (4.3 L). Warm the engine, shut it down or switch the hybrid system off, wait more than five minutes on level ground, add below the reference quantity first and finish from the dipstick.",values:[{label:"2020 3.5L with towing package",value:"5.8 US qt",note:"5.5 L with filter"},{label:"2020 3.5L without towing package",value:"5.7 US qt",note:"5.4 L with filter"},{label:"2020 without filter",value:"5.6 US qt",note:"5.3 L; normal service should replace filter"},{label:"2021+ 2.5L hybrid",value:"4.5 US qt",note:"4.3 L with filter in cited 2024 manual"},{label:"Generation break",value:"2021 model year",note:"V6 ended; A25A-FXS hybrid began"}],source:toyotaSienna2020,sources:[toyotaSienna2020,toyotaSienna2024,S.toyota],reviewed:"2026-08-21",diagram:"oil"},
  {slug:"dodge/grand-caravan/spark-plug-specs",keyword:"dodge grand caravan spark plug specs",make:"Dodge",model:"2011–2019 Grand Caravan 3.6L",category:"Ignition Specs",title:"Dodge Grand Caravan 3.6 Spark Plug Gap, Torque and Interval",answer:"The covered 3.6L Pentastar service specification uses a 0.043-in (1.1-mm) plug gap and 13 lb-ft (17.5 N·m) installation torque. Mopar's 2019 schedule calls for replacement at 100,000 miles.",scope:"The torque row is anchored to the 2011 Grand Caravan 3.6L service information and the interval to the 2019 3.6L guide. Verify the exact approved plug for the VIN before servicing another year. Older 3.3L, 3.8L and 4.0L engines use different plugs and must not inherit this Pentastar row.",detail:"Work on a cold engine, remove debris from each plug well and start every plug by hand. The 13-lb-ft value assumes clean, undamaged threads and the specified gasket-seat plug; anti-seize changes friction and can lead to excessive clamp load unless the plug maker explicitly accounts for it. Replace damaged fine-wire plugs rather than aggressively bending the electrodes.",values:[{label:"3.6L plug gap",value:"0.043 in",note:"1.1 mm; approved plug only"},{label:"3.6L installation torque",value:"13 lb-ft",note:"17.5 N·m; cold clean threads"},{label:"2019 replacement interval",value:"100,000 mi",note:"160,000 km; mileage based"},{label:"Plug quantity",value:"6",note:"One coil-on-plug unit per cylinder"},{label:"3.3L / 3.8L / 4.0L",value:"Separate specification",note:"Do not transfer Pentastar values"}],source:grandCaravan2011Spark,sources:[grandCaravan2011Spark,grandCaravan2019Guide,S.mopar],diagram:"spark",engine:true},
  {slug:"bmw/x1/wheel-torque",keyword:"bmw x1 wheel torque specifications",make:"BMW",model:"X1",category:"Torque Specs",title:"BMW X1 Wheel Bolt Torque: 140 N-m Application Guide",answer:"BMW X1 factory wheel-bolt applications commonly use 140 N·m (103 lb-ft), but the VIN-specific owner's information and any accessory-wheel instructions remain controlling.",scope:"This page covers the conventional five-bolt factory-wheel arrangement used across common E84, F48 and U11 X1 applications. It does not automatically apply to a conversion using studs and nuts, non-BMW wheels, spacers or hardware with a different seat.",detail:"Clean and inspect the wheel bolts and their seats, never oil the threads, seat the wheel flat against the hub and hand-start all five bolts. Tighten progressively in a crosswise pattern and use a calibrated torque wrench for the final 140-N·m pass. Check the exact vehicle manual by VIN before treating the value as final.",values:[{label:"Common X1 wheel-bolt torque",value:"140 N·m",note:"103 lb-ft"},{label:"Tightening pattern",value:"Five-bolt crosswise",note:"Progressive passes"},{label:"Thread condition",value:"Clean and dry",note:"Do not oil BMW wheel bolts"},{label:"Aftermarket wheel or stud conversion",value:"Hardware-maker specification",note:"Factory value may not transfer"}],source:bmwX1Manuals,sources:[bmwX1Manuals,S.bmw],diagram:"wheel"},
  {slug:"nissan/versa/tire-pressure",keyword:"nissan versa tire pressure specs",make:"Nissan",model:"2020 Versa",category:"Vehicle Specifications",title:"2020 Nissan Versa Tire Pressure: 33 PSI for Every Factory Size",answer:"Nissan specifies 33 psi (230 kPa) cold at both axles for the 2020 Versa's 195/65R15, 205/55R16 and 205/50R17 factory tires. The temporary spare is 60 psi (420 kPa).",scope:"This chart is for the U.S.-market 2020 Versa sedan. It does not cover the older Versa Note, another model year, an alternate-size tire or a vehicle whose tire-and-loading label states a different value.",detail:"Nissan defines cold tires as those on a vehicle parked for at least three hours or driven less than 1 mile (1.6 km) at moderate speed. Check with an accurate gauge before driving, reinstall the valve caps and use the driver's-door placard—not the tire sidewall maximum—as the target.",values:[{label:"195/65R15 front and rear",value:"33 psi cold",note:"230 kPa"},{label:"205/55R16 front and rear",value:"33 psi cold",note:"230 kPa"},{label:"205/50R17 front and rear",value:"33 psi cold",note:"230 kPa"},{label:"T125/70D15 temporary spare",value:"60 psi cold",note:"420 kPa"},{label:"Nissan cold definition",value:"Parked 3+ hours",note:"Or driven under 1 mi / 1.6 km"}],source:nissanVersa2020,diagram:"wheel"},
  {slug:"jeep/wrangler/axle-torque",keyword:"jeep wrangler axle torque specs",make:"Jeep",model:"2009–2010 Wrangler JK",category:"Torque Specs",title:"Jeep Wrangler JK Axle Torque Specs: Hub, Track Bar and Arms",answer:"For the covered JK front hub, tighten the three hub-to-knuckle bolts to 75 lb-ft (102 N·m) and the front axle nut to 100 lb-ft (136 N·m). The cited suspension procedure uses 148 lb-ft for axle-side track-bar bolts with vehicle weight on the suspension.",scope:"The hub values are anchored to a 2009 4WD Wrangler 3.8L and the suspension rows to a 2010 JK recall procedure. They do not describe every YJ, TJ, later 3.6L JK, JL, Dana axle or internal differential fastener.",detail:"Rubber-bushed control-arm and track-bar fasteners in the cited procedure are tightened with full vehicle weight on the suspension. Pinion nuts and differential bearing caps are intentionally excluded: pinion tightening establishes bearing preload and requires measured rotating torque, while caps must remain paired and oriented.",values:[{label:"Front hub-to-knuckle bolts",value:"75 lb-ft",note:"102 N·m; three bolts"},{label:"Front axle shaft nut",value:"100 lb-ft",note:"136 N·m; covered 2009 JK"},{label:"Front/rear track bar to axle",value:"148 lb-ft",note:"200 N·m; suspension loaded"},{label:"Front lower arm to axle",value:"140 lb-ft",note:"189 N·m; covered procedure"},{label:"Rear upper arm to axle",value:"150 lb-ft",note:"203 N·m; covered procedure"},{label:"Pinion nut",value:"Preload procedure only",note:"Never substitute a generic final torque"}],source:jeepWrangler2009Hub,sources:[jeepWrangler2009Hub,jeepWrangler2010Suspension,S.mopar],diagram:"main"},
  {slug:"subaru/outback/tire-pressure",keyword:"subaru outback tire pressure specifications",make:"Subaru",model:"2020 Outback",category:"Vehicle Specifications",title:"2020 Subaru Outback Tire Pressure: 35 Front, 33 Rear",answer:"The 2020 Subaru Outback's common factory 225/65R17 and 225/60R18 packages use 35 psi cold at the front and 33 psi cold at the rear.",scope:"These figures cover the 2020 U.S.-market Outback factory tire packages represented here. Wilderness arrived later and uses its own tire, wheel and label information; another model year or replacement tire size must be checked at the driver's-door tire-inflation label.",detail:"Check the tires before driving or after enough time for them to return to ambient temperature. A warm reading will normally be higher, so do not bleed a hot tire down to the cold target. Use the dashboard pressure display as a monitoring aid, but use a reliable handheld gauge and the door label when setting the baseline.",values:[{label:"225/65R17 front",value:"35 psi cold",note:"Factory 17-inch package"},{label:"225/65R17 rear",value:"33 psi cold",note:"Factory 17-inch package"},{label:"225/60R18 front",value:"35 psi cold",note:"Factory 18-inch package"},{label:"225/60R18 rear",value:"33 psi cold",note:"Factory 18-inch package"},{label:"Sidewall pressure",value:"Not the vehicle target",note:"Use Subaru's door label"}],source:subaruOutback2020,sources:[subaruOutback2020,S.subaru],diagram:"wheel"},
];
const researchedEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "dodge/dart/firing-order":{sections:[{heading:"Firing order versus cylinder number",paragraphs:["Cylinder numbers stay in physical order from the timing-drive end: 1-2-3-4. The crankshaft's combustion sequence is 1-3-4-2. These two lists answer different questions and should not be substituted for one another.","A P0302 code identifies physical cylinder 2 even though cylinder 2 fires fourth in the sequence. Locate the cylinder first, then test its coil, plug, injector, compression and wiring rather than following the order around an imaginary distributor cap."]},{heading:"Why there is no plug-wire diagram",paragraphs:["The 2.0L Tigershark uses an individual coil over each plug. The PCM controls coil timing from crankshaft and camshaft signals, so there are no high-voltage plug wires to arrange in 1-3-4-2 order.","The 1.4L turbo and 2.4L Dart also require their own component and timing procedures. A classic Dart may have a Slant Six or V8 distributor, so the modern PF-platform diagram must never be transferred by model name alone."]}],faqs:[{q:"What is the 2013 Dodge Dart 2.0 firing order?",a:"The firing order is 1-3-4-2."},{q:"Where is cylinder 1 on the Dart 2.0L?",a:"Cylinder 1 is at the timing-drive end, with cylinders 2, 3 and 4 continuing toward the transmission."},{q:"Does P0303 mean the third cylinder in the firing sequence?",a:"No. It identifies physical cylinder 3, regardless of where that cylinder appears in 1-3-4-2."},{q:"Does the 2.0L Dart have distributor plug wires?",a:"No. It uses coil-on-plug ignition controlled electronically by the PCM."}]},
  "subaru/brz/wheel-torque":{sections:[{heading:"How to apply 120 N-m evenly",paragraphs:["Hand-start all five nuts, snug them in an opposite-side star pattern while the wheel can still center, then finish at 120 N·m after the tire is supporting enough load to prevent rotation. Use the same calibrated setting at every position.","An impact wrench can install a nut too tightly before the torque wrench is used. If an impact is used for removal or light preliminary seating, keep the final controlled pass separate."]},{heading:"Mounting surfaces and replacement hardware",paragraphs:["Remove corrosion and trapped debris from the hub and wheel faces so the wheel sits flush. Keep the threads and tapered seats clean and in the condition Subaru specifies; lubricant changes the relationship between wrench torque and stud tension.","An aftermarket wheel can require a different seat shape, shank length or nut diameter. Verify brake clearance and load rating as well as bolt circle, and follow the wheel manufacturer if its hardware instructions supersede the factory nut arrangement."]}],faqs:[{q:"What is the 2013 Subaru BRZ wheel-nut torque?",a:"Subaru specifies 120 N·m, approximately 89 lb-ft."},{q:"What tightening pattern should be used?",a:"Use progressive opposite-side passes in a five-lug star pattern."},{q:"Can an impact wrench provide the final torque?",a:"Use a calibrated torque wrench for the final pass at every nut."},{q:"Do aftermarket BRZ wheels always use 120 N-m?",a:"No. Confirm the replacement wheel's seat geometry and hardware instructions."}]},
  "nissan/murano/spark-plug-gap":{sections:[{heading:"Standard gap and wear limit are different",paragraphs:["Nissan lists 1.1 mm as the standard gap and 1.4 mm as the service limit for the covered VQ35DE. The limit is not an alternate setup target; it marks excessive electrode wear.","Measure carefully with a suitable wire gauge only when inspection is required. If the fine-wire electrode is worn, rounded or outside the limit, replace the plug rather than bending it back and extending service life artificially."]},{heading:"Choose the plug by specification, not gap alone",paragraphs:["A plug can measure 0.043 inch yet have the wrong reach, seat, heat range, resistor or projected tip. Use Nissan's approved part number or a documented exact equivalent for the model year.","Inspect removed plugs by cylinder and keep them organized. A single oil-fouled or unusually white plug may reveal a mechanical, fueling or cooling problem that installing six new plugs will temporarily hide rather than repair."]}],faqs:[{q:"What is the 2011 Nissan Murano spark-plug gap?",a:"The standard VQ35DE gap is 1.1 mm (0.043 in)."},{q:"What is the Murano spark-plug wear limit?",a:"Nissan lists 1.4 mm (0.055 in) for the covered application."},{q:"Should an iridium plug be regapped when worn?",a:"No. Replace a damaged or out-of-limit fine-wire plug with the approved part."},{q:"Can any 0.043-inch plug be installed?",a:"No. Reach, seat design, heat range and the exact approved part are equally important."}]},
  "jeep/renegade/tire-size":{sections:[{heading:"Read the complete tire code before ordering",paragraphs:["The first number is section width in millimeters, the second is sidewall height as a percentage of width and the final number is wheel diameter. That is why 215/60R17 and 215/65R17 are not interchangeable labels even though both fit a 17-inch wheel.","Match the full size, load index, speed symbol and service description on the vehicle label. A tire that physically mounts can still have the wrong load capability or outside diameter for ABS, stability control and driveline operation."]},{heading:"Traction-device clearance is trim specific",paragraphs:["The 2017 guide allows only a low-profile 7-mm device on the front of the two smaller road-tire applications. It specifically excludes the Trailhawk 215/65R17 and the 225/55R18 packages because clearance is not adequate.","Install devices tightly, remove damaged devices immediately, avoid full-lock wheelspin and observe the 30-mph limit. Recheck tension after the first half mile instead of assuming the first installation has seated permanently."]}],faqs:[{q:"What tire sizes came on a 2017 Jeep Renegade?",a:"The guide lists 215/65R16, 215/60R17, 215/65R17 Trailhawk and 225/55R18 applications."},{q:"Is every 17-inch Renegade tire the same size?",a:"No. Standard applications use 215/60R17 while the cited Trailhawk application uses 215/65R17."},{q:"Can chains be fitted to a 2017 Renegade Trailhawk?",a:"The factory guide marks the 215/65R17 Trailhawk application as not chainable."},{q:"Where should tire pressure be found?",a:"Use the tire-and-loading label on the vehicle; tire size alone does not determine the target pressure."}]},
  "toyota/prius/tire-pressure":{sections:[{heading:"Why the 15- and 17-inch rows differ",paragraphs:["Toyota balances tire construction, load capacity and handling as a complete package. The lower-profile 215/45R17 tire therefore uses a different cold setting from the 195/65R15 tire; equalizing all four tires to a remembered Prius number discards that engineering distinction.","Find the size molded on the tire and confirm it against the door label before selecting the chart row. If the car has replacement wheels or a nonstandard size, ask the tire and vehicle specialists for a documented pressure rather than guessing from diameter."]},{heading:"Set pressure cold and interpret TPMS correctly",paragraphs:["Pressure increases as the tire warms in use. Set the baseline before driving and do not bleed a warm tire merely because the dashboard number is above the cold label value.","TPMS is a warning system, not a substitute for monthly gauge checks. Correct all four tires, inspect any tire that repeatedly loses pressure and follow Toyota's initialization procedure after tire service when the manual requires it."]}],faqs:[{q:"What is the 2020 Prius pressure with 15-inch tires?",a:"Use 36 psi cold at the front and 35 psi cold at the rear for the cited 195/65R15 package."},{q:"What is the 2020 Prius pressure with 17-inch tires?",a:"Use 33 psi cold at the front and 32 psi cold at the rear for the cited 215/45R17 package."},{q:"Should all four Prius tires use the same pressure?",a:"No. Both factory rows use a slightly higher front setting than rear."},{q:"Is the number on the tire sidewall the correct target?",a:"No. Use Toyota's tire-and-loading label; the sidewall figure is not the normal vehicle setting."}]},
  "dodge/grand-caravan/spark-plug-specs":{sections:[{heading:"Installation details that protect the aluminum head",paragraphs:["Let the engine cool, disconnect each coil carefully and remove loose grit from the plug wells before the plugs come out. Debris entering the cylinder or a plug started at an angle can turn routine maintenance into cylinder-head repair.","Thread each plug in by hand through several complete turns. Apply the final 17.5-N·m value only after the gasket-seat plug is seated normally; the service information warns that excessive torque can stretch the shell and impair heat transfer."]},{heading:"Use the interval as an inspection opportunity",paragraphs:["The 2019 maintenance schedule places plug replacement at 100,000 miles and says the interval is mileage based. Earlier replacement may be justified by a confirmed ignition fault, contamination or damage, but a misfire code should still be diagnosed rather than answered with six parts automatically.","Keep removed plugs organized by cylinder. Oil deposits, fuel wetting, cracked porcelain or one unusually eroded electrode can point to a coil, injector, sealing or mixture problem that deserves a separate test."]}],faqs:[{q:"What is the Grand Caravan 3.6L spark-plug gap?",a:"The covered Pentastar application uses 0.043 in (1.1 mm)."},{q:"What is the 3.6L spark-plug torque?",a:"The covered service specification is 13 lb-ft (17.5 N·m)."},{q:"When does the 2019 guide replace the plugs?",a:"At 100,000 miles (160,000 km); the schedule says this interval is mileage based."},{q:"Do the 3.3L and 3.8L engines use these values?",a:"Do not assume so. Those older engines require their own year, plug and torque specification."}]},
  "bmw/4-series/wheel-torque":{sections:[{heading:"Correct BMW wheel-bolt tightening procedure",paragraphs:["With the wheel flush on the hub, hand-start all five bolts and snug them in a crosswise sequence so the wheel centers without being pulled sideways. Lower the vehicle enough to prevent rotation, then complete the final 140-N·m pass with a calibrated wrench.","An impact wrench can exceed the target before a torque wrench clicks and may damage a locking-bolt adapter. Use powered tools for removal only and keep final tightening controlled by hand."]},{heading:"When the factory value no longer transfers",paragraphs:["A stud conversion changes bolts into studs and nuts; spacers may change thread engagement; aftermarket wheels may use a different seat. Each modification needs the hardware supplier's documented torque and fitment instructions.","Inspect for stretched, corroded or damaged bolts and make sure no bolt bottoms before clamping the wheel. Paint buildup or corrosion between the wheel and hub can also create false seating that relaxes after driving."]}],faqs:[{q:"What is the BMW F32/F36 4 Series wheel-bolt torque?",a:"The covered standard factory-wheel specification is 140 N·m (103 lb-ft)."},{q:"Should BMW wheel bolts be lubricated?",a:"No. Keep the threads and tapered seats clean and dry unless an exact BMW procedure expressly says otherwise."},{q:"How should five BMW 4 Series wheel bolts be sequenced?",a:"Tighten progressively in a five-bolt crosswise sequence."},{q:"Does 140 N-m automatically apply after a stud conversion?",a:"No. Follow the conversion hardware and wheel manufacturer's documented specification."}]},
  "bmw/x1/wheel-torque":{sections:[{heading:"A repeatable five-bolt workflow",paragraphs:["Support the wheel squarely against the hub and start every bolt by hand. Snug in a crosswise sequence, then make one controlled final pass at 140 N·m with a calibrated wrench so one bolt does not carry the wheel off-center.","Clean the mating faces and wheel pilot without coating the bolt threads in oil. Lubrication changes friction and can produce more bolt tension than the dry specification intended."]},{heading:"Verify changed wheels and hardware separately",paragraphs:["Factory-style bolts use a specific seat and length. A wheel that accepts the bolt circle can still require a different seat, may reduce thread engagement or may not clear the brake hardware.","For spacers, stud conversions, locks and non-BMW wheels, follow documented component instructions and inspect fitment before road use. The strongest-looking hardware does not make a mismatched seat safe."]}],faqs:[{q:"What is the common BMW X1 wheel-bolt torque?",a:"The common factory application is 140 N·m, or 103 lb-ft, subject to VIN verification."},{q:"Can the final pass be done with an impact wrench?",a:"No. Use a calibrated torque wrench and tighten crosswise."},{q:"Should X1 wheel bolts be oiled?",a:"No. BMW wheel bolts are installed with clean, dry threads for this specification."},{q:"Do aftermarket X1 wheels always use 140 N-m?",a:"No. Seat shape, bolt length and the wheel or hardware maker's instructions must be checked."}]},
  "nissan/versa/tire-pressure":{sections:[{heading:"One pressure across three factory wheel sizes",paragraphs:["Nissan assigns the same 33-psi cold setting to the listed 15-, 16- and 17-inch 2020 Versa road tires. This is useful only after the tire size and model year are confirmed; it is not a generation-wide rule for every Versa or Versa Note.","The temporary spare is intentionally much higher at 60 psi. Check it periodically while it is stored, because a soft spare discovered during a roadside event is not useful."]},{heading:"Cold pressure and temperature changes",paragraphs:["A tire qualifies as cold under Nissan's definition after at least three parked hours or less than one mile of moderate driving. Measure then, before road heat raises the reading.","Ambient temperature can lower all four tires together, while a puncture often produces a continuing loss in one position. Restore the placard pressure, inspect for damage and investigate a tire that falls again instead of repeatedly clearing the warning."]}],faqs:[{q:"What is the 2020 Nissan Versa tire pressure?",a:"Set all four factory road tires to 33 psi (230 kPa) when cold."},{q:"Does the answer change between 15-, 16- and 17-inch factory tires?",a:"Not in the cited 2020 manual; all three listed sizes use 33 psi front and rear."},{q:"What pressure does the temporary spare use?",a:"The T125/70D15 temporary spare uses 60 psi (420 kPa) cold."},{q:"How does Nissan define a cold tire?",a:"Parked for at least three hours or driven less than 1 mile (1.6 km) at moderate speed."}]},
  "subaru/outback/tire-pressure":{sections:[{heading:"The front and rear targets are intentionally different",paragraphs:["The cited 2020 Outback packages use 35 psi at the front and 33 psi at the rear. Do not average them or inflate every position to the higher number; the split accounts for the vehicle's axle loading and handling calibration.","Both the 17-inch 225/65R17 and 18-inch 225/60R18 factory packages use the same pair in this application, but the door label remains the decisive check after any wheel, tire or trim change."]},{heading:"Using the dashboard pressure display",paragraphs:["The display is convenient for spotting a falling tire while driving and Subaru permits the unit to be switched between kPa and psi. Sensor readings may not appear immediately after startup and can differ slightly from a handheld gauge.","Set the cold baseline with a reliable gauge, then treat the display as a trend monitor. A repeated one-wheel drop calls for a valve, bead and tread inspection rather than simply adding air every few days."]}],faqs:[{q:"What is the 2020 Subaru Outback cold tire pressure?",a:"Use 35 psi at the front and 33 psi at the rear for the cited factory packages."},{q:"Do the factory 17- and 18-inch packages use the same pressure?",a:"Yes, the cited 225/65R17 and 225/60R18 packages both use 35 psi front and 33 psi rear."},{q:"Should a warm tire be bled down to 35 or 33 psi?",a:"No. Set the target cold; normal driving heat raises pressure."},{q:"Does this apply to an Outback Wilderness?",a:"Do not assume so. Check the Wilderness model-year door label and owner information."}]},
  "nissan/titan/towing-capacity":{sections:[{heading:"Choose TITAN or TITAN XD before reading the number",paragraphs:["The TITAN XD is not simply a trim with the same chassis rating. Nissan gives it separate payload, conventional-towing and gooseneck rows, while the ordinary TITAN varies again by cab and drivetrain.","Use the VIN and build information to identify the truck, then confirm hitch equipment and the certification labels. A brochure maximum is only the top of one qualifying configuration, not a substitute for the actual truck's ratings."]},{heading:"Loaded truck weight changes usable trailer capacity",paragraphs:["Nissan's manual demonstrates the calculation with the truck weighed as it will travel. Subtract actual vehicle weight from GCWR and compare that result with the chart maximum; the lower figure governs.","Tongue or king-pin weight also consumes payload and axle capacity. Add passengers, cargo, accessories and hitch hardware, then weigh the combination instead of treating the trailer's empty weight as its road-ready weight."]}],faqs:[{q:"What is the maximum 2024 Nissan TITAN towing capacity?",a:"The ordinary TITAN reaches 9,290 lb in the cited Crew Cab 4x2 row."},{q:"How much can the 2024 TITAN XD tow?",a:"Up to 10,900 lb conventionally or 11,050 lb with a qualifying gooseneck setup."},{q:"Does every TITAN XD tow 11,050 lb?",a:"No. That is a properly equipped gooseneck maximum; configuration and loaded-vehicle limits still apply."},{q:"How much tongue weight should a conventional trailer carry?",a:"Nissan generally directs owners toward 10–15 percent while remaining within every vehicle and hitch limit."}]},
  "ram/3500/towing-capacity":{sections:[{heading:"What builds the 37,090-lb configuration",paragraphs:["The headline rating requires a specific high-output Cummins/Aisin, 4.10-axle, two-wheel-drive, regular-cab, long-bed dual-rear-wheel combination. Removing any one of those assumptions can move the truck into a lower chart row.","A Crew Cab or Mega Cab, four-wheel drive, single rear wheels, another axle or the standard-output engine carries different curb weight and GCWR. Decode the truck before selecting a number by engine badge alone."]},{heading:"Maximum payload and maximum towing are different trucks",paragraphs:["Ram explicitly notes that trailer and payload maxima are mutually exclusive. The light gas-engine configuration that produces the largest payload is not the heavy diesel combination that produces maximum trailer weight.","Fifth-wheel pin weight can become the limiting load even when the trailer is below 37,090 lb. Add occupants, bed cargo, hitch assembly and pin load and compare the result with the door-label payload and both axle ratings."]}],faqs:[{q:"What is the maximum 2024 Ram 3500 towing capacity?",a:"Ram publishes 37,090 lb for one qualifying high-output Cummins configuration."},{q:"Which Ram 3500 configuration reaches 37,090 lb?",a:"A 4x2 regular-cab long-bed dual-rear-wheel truck with the HO 6.7L Cummins, Aisin transmission and 4.10 axle."},{q:"Can a 4x4 Crew Cab tow the same amount?",a:"Do not assume so. Cab, drivetrain, bed, axle and wheel arrangement select a different chart row."},{q:"Is the 7,680-lb maximum payload available with maximum towing?",a:"No. Ram states payload and trailer-weight maxima are mutually exclusive and occur on different configurations."}]},
  "chevrolet/camaro/horsepower-by-year":{sections:[{heading:"The three final-year engine levels",paragraphs:["The 3.6L V6 provides 335 hp, the LT1 V8 in LT1 and SS models provides 455 hp, and the ZL1's supercharged LT4 provides 650 hp. The engine code matters more than appearance packages or the shared 6.2-liter displacement of the two V8s.","A Camaro LT1 is a trim equipped with the LT1 engine. An SS also uses that 455-hp LT1 but adds its own chassis, cooling and equipment content; a ZL1 uses the distinct supercharged LT4."]},{heading:"Why this page stops at 2024",paragraphs:["Chevrolet identified 2024 as the sixth generation's final model year. Keeping this table to that year avoids mixing early gross-rated horsepower, later SAE net figures and aftermarket claims into one misleading progression.","When comparing an older Camaro, match year, engine, transmission and the rating standard in a contemporary Chevrolet source. Similar badges across generations do not guarantee similar hardware or output."]}],faqs:[{q:"How much horsepower does a 2024 Camaro V6 make?",a:"Chevrolet rates the 3.6L V6 at 335 hp."},{q:"How much horsepower does the 2024 Camaro SS make?",a:"The naturally aspirated 6.2L LT1 V8 is rated at 455 hp."},{q:"What is the 2024 Camaro ZL1 horsepower?",a:"Its supercharged 6.2L LT4 is rated at 650 hp."},{q:"Does the Camaro LT1 trim make less power than the SS?",a:"No. Both cited 2024 models use the 455-hp LT1 V8, though their equipment packages differ."}]},
  "bmw/m5/horsepower-by-year":{sections:[{heading:"System output is not V8-only output",paragraphs:["The 717-hp number belongs to the complete M Hybrid system. Quoting it as the 4.4L V8's standalone rating would erase the electric motor's contribution and make comparisons with earlier non-hybrid M5 generations inaccurate.","BMW similarly publishes 738 lb-ft as system torque. Power delivery depends on coordinated combustion-engine, motor, battery, transmission and M xDrive operation rather than one engine dyno curve alone."]},{heading:"How the G90 differs from the F90",paragraphs:["The prior F90 used a non-hybrid twin-turbo V8 and appeared in standard, Competition and CS ratings. The G90 adds plug-in hybrid hardware, substantially changes vehicle mass and should be compared as a new architecture rather than a simple horsepower update.","Use BMW's market-specific technical table because horsepower units, equipment and model designation can differ outside the United States. Chassis-dyno results are also not factory crankshaft/system ratings."]}],faqs:[{q:"How much horsepower does the 2025 BMW M5 have?",a:"BMW rates the G90 M5 at 717 hp of combined system output."},{q:"How much torque does the G90 M5 produce?",a:"The published combined system rating is 738 lb-ft."},{q:"Is 717 hp produced by the V8 alone?",a:"No. It is the M Hybrid system output from the V8 and electric drive together."},{q:"Can maximum power remain available with no displayed electric range?",a:"BMW says an energy buffer is maintained and replenished under normal operation, although operating protections and conditions still apply."}]},
  "chevrolet/corvette/horsepower-by-year":{sections:[{heading:"What makes the LT7 a separate Corvette engine",paragraphs:["The LT7 is not a turbo kit added to the Z06's LT6. Chevrolet specifies twin turbochargers, port plus direct fuel injection, unique calibration and a 9.8:1 compression ratio around its 5.5L flat-plane architecture.","Its 1,064-hp rating is achieved at 7,000 rpm under SAE guidelines. The Z06's naturally aspirated 670-hp LT6, Stingray LT2 and hybrid E-Ray combination require their own rows and service information."]},{heading:"Horsepower does not describe the whole configuration",paragraphs:["Chevrolet offers standard and high-downforce ZTK aerodynamic arrangements without changing the published engine rating. Downforce, tires, suspension and gearing affect track behavior even when the engine number remains 1,064 hp.","Keep later ZR1X references separate: its combined hybrid output includes a front-axle electric motor. That is not a retroactive rating for the 2025 rear-drive ZR1 described here."]}],faqs:[{q:"How much horsepower does the 2025 Corvette ZR1 make?",a:"Chevrolet specifies 1,064 hp at 7,000 rpm under SAE guidelines."},{q:"What is the 2025 ZR1 torque rating?",a:"The twin-turbo LT7 produces 828 lb-ft at 6,000 rpm."},{q:"Is the LT7 the same engine as the Z06 LT6?",a:"No. Both are 5.5L flat-plane DOHC V8s, but the LT7 is a distinct twin-turbo engine with different induction and fueling."},{q:"Does the ZTK package increase engine horsepower?",a:"No. It changes aerodynamic, tire and suspension equipment while the published engine rating remains 1,064 hp."}]},
  "bmw/x3/brake-rotor-size":{sections:[{heading:"Why VIN identification matters on an F25",paragraphs:["BMW notes that engine, transmission, national version and load-related options can change the brake disc. A 328-mm listing on a parts site is not enough if the caliper or option package on the vehicle differs.","Use the VIN in BMW's parts system and compare the old disc's dimensions and part number before ordering. Diameter alone cannot distinguish two rotors with different thickness, offset or ventilation geometry."]},{heading:"Measure thickness away from the wear lip",paragraphs:["Clean the disc and measure at several evenly spaced points in the swept area with a brake micrometer. Avoid the unworn outer ridge, which can make a worn disc appear thicker than it is.","Replace the covered standard disc at or below 26.4 mm and inspect both sides for scoring, heat checks and thickness variation. BMW applies a different total-wear rule to perforated and M discs, so do not borrow this limit for those systems."]}],faqs:[{q:"What is the 2013 BMW X3 xDrive28i front rotor size?",a:"The covered standard F25 brake uses a 328 x 28 mm ventilated front rotor."},{q:"What is the minimum thickness for that 328-mm disc?",a:"The cited service row lists 26.4 mm; the stamped MIN TH and VIN-confirmed specification control."},{q:"Do all F25 X3 models use a 328-mm front rotor?",a:"No. Engine, market and brake-option equipment can select another disc."},{q:"Can rotor thickness be measured across the outer ridge?",a:"No. Measure the swept surface at multiple points away from the unworn lip."}]},
  "honda/hr-v/spark-plug-torque":{sections:[{heading:"Protect the cylinder-head threads",paragraphs:["Remove the coils only after clearing dirt from the top of the engine, and blow or vacuum loose debris from each well before loosening a plug. Start the replacement through several full turns by hand so cross-threading is obvious before torque is applied.","Use a small-range torque wrench suited to 18 N·m. A large wheel-lug wrench near the bottom of its range may be less controlled, and an impact tool has no place in final spark-plug installation."]},{heading:"The approved plug is part of the specification",paragraphs:["Correct torque cannot rescue a plug with the wrong reach, gasket seat, heat range or projection. Confirm the Honda part or documented exact equivalent using the VIN and engine.","Inspect the old plugs by cylinder. Oil deposits, fuel wetness or one unusually eroded electrode may point to a mechanical or ignition fault that replacement alone will not diagnose."]}],faqs:[{q:"What is the 2016–2021 Honda HR-V 1.8L spark-plug torque?",a:"The covered service procedure specifies 18 N·m (13 lb-ft)."},{q:"Should HR-V spark plugs be started with a ratchet?",a:"Start them by hand through several turns, then use the torque wrench only after correct engagement is certain."},{q:"Does this torque apply to the 2023 HR-V 2.0L?",a:"Do not assume so; the newer engine requires its own service procedure."},{q:"Can any gasket-seat plug be used if tightened to 18 N-m?",a:"No. Reach, heat range, projection and the approved exact application also matter."}]},
  "bmw/7-series/battery-replacement":{sections:[{heading:"Registration and coding solve different problems",paragraphs:["Registration tells the energy-management system that a new battery has been fitted and records the replacement. It lets the charging strategy stop treating the battery as an aged unit.","Coding changes the vehicle's configured battery class when capacity or chemistry changes. A like-for-like replacement normally still requires registration, while a deliberate AGM/lead-acid or amp-hour change may require both coding and registration."]},{heading:"Identify multi-battery and high-voltage systems first",paragraphs:["Later 7 Series vehicles may carry an auxiliary battery, 48-volt system or high-voltage hybrid battery in addition to the conventional 12-volt battery. Each has a separate isolation and replacement procedure.","Read the existing labels and VIN equipment before disconnecting power. Do not bridge, charge or substitute across voltage systems, and use BMW's approved diagnostic/service functions after installation."]}],faqs:[{q:"Does a replacement BMW 7 Series battery need registration?",a:"Yes. BMW's service bulletin requires the replacement battery to be registered with diagnostic equipment."},{q:"Is registration the same as coding?",a:"No. Registration records replacement; coding changes the configured chemistry or capacity when necessary."},{q:"What amp-hour battery does every 7 Series use?",a:"There is no universal number. Match the VIN, original label, installed systems and coded battery class."},{q:"Can a 48-volt battery be serviced like the 12-volt battery?",a:"No. It requires its own safety, isolation, replacement and registration procedure."}]},
  "honda/civic/brake-rotor-torque":{sections:[{heading:"Separate the four fastener jobs",paragraphs:["The 108-N·m figure belongs to the bracket-to-knuckle bolts and the wheel nuts in this covered application. The caliper bolts and hydraulic banjo bolt use much lower, separate values.","The slip-on rotor does not receive bracket-bolt torque. Keeping each number attached to its named fastener prevents stripped slide-pin threads, crushed hose washers and unsafe bracket installation."]},{heading:"Runout begins at the hub surface",paragraphs:["Rust or debris trapped between hub and rotor can create lateral runout even when the new disc is true. Clean both mating faces and keep grease away from the pad tracks.","Honda's procedure clamps the rotor with flat washers and wheel nuts before dial-indicator measurement. If the reading exceeds the service limit, follow the approved indexing/refinishing or replacement procedure rather than assuming the rotor is warped by sight."]}],faqs:[{q:"What is the 2012 Civic front caliper-bracket torque?",a:"The covered 1.8L front bracket bolts use 108 N·m (80 lb-ft)."},{q:"What is the front caliper-bolt torque on this application?",a:"The cited branch lists 34 N·m (25 lb-ft)."},{q:"Does the brake rotor itself get tightened to 108 N-m?",a:"No. The rotor slips over the hub; 108 N·m belongs to the bracket bolts and wheel nuts here."},{q:"Can old banjo-bolt sealing washers be reused?",a:"The cited procedure requires new sealing washers and 35 N·m (26 lb-ft) on the banjo bolt."}]},
  "hyundai/sonata/spark-plug-gap":{sections:[{heading:"Do not combine turbo and naturally aspirated rows",paragraphs:["Turbocharged cylinders operate at higher charge pressure, and the covered LF branch uses the narrower 0.7–0.8 mm range. Copying a roughly 1.0–1.1 mm naturally aspirated figure can create misfire under boost.","Confirm the engine code and approved plug part before measurement. Model name and year alone may still include 2.4L, 2.0T and hybrid powertrains with different ignition requirements."]},{heading:"Handle fine-wire electrodes as precision parts",paragraphs:["Measure with a wire-style gauge and avoid pushing against the center electrode or porcelain. A plug supplied outside its documented specification or damaged in shipping should be replaced rather than repeatedly bent.","A recurring misfire after correct plugs are installed calls for coil, injector, compression, boost-leak and wiring diagnosis. Closing the gap beyond Hyundai's range is not a sound substitute for finding the fault."]}],faqs:[{q:"What is the covered Hyundai Sonata LF turbo plug gap?",a:"The cited service branch specifies 0.7–0.8 mm (0.0275–0.0314 in)."},{q:"Does the Sonata 2.4L GDI use the same gap?",a:"Do not transfer this turbo value; confirm the wider 2.4L specification and exact plug separately."},{q:"Can a coin-style tool be used on the fine-wire plug?",a:"Avoid tools or techniques that press on the center electrode; use a suitable wire gauge and replace damaged plugs."},{q:"Will a smaller gap fix a turbo misfire?",a:"Do not close the gap outside specification to mask an ignition, fueling, boost or mechanical fault."}]},
  "jeep/wrangler/axle-torque":{sections:[{heading:"Hub hardware versus suspension hardware",paragraphs:["The hub-to-knuckle bolts clamp the unit bearing and the axle nut secures the shaft/hub relationship. Control-arm and track-bar bolts locate the axle under the chassis and have different loads and installation conditions.","Label removed fasteners and attach every value to a named position. A memorized 100 or 148 lb-ft number is unsafe when applied to the wrong component."]},{heading:"Load rubber bushings before final tightening",paragraphs:["The cited recall procedure requires full vehicle weight on the suspension for the control-arm, track-bar, stabilizer and shock fasteners. Tightening bonded-rubber bushings at full droop can preload and shorten their life.","Internal differential work is outside this chart. Bearing-cap position and pinion preload are assembly measurements, not generic bolt-list jobs, and require the exact Dana axle procedure and measuring tools."]}],faqs:[{q:"What is the 2009 JK front axle-nut torque?",a:"The covered 4WD 3.8L procedure specifies 100 lb-ft (136 N·m)."},{q:"What are the three JK hub-to-knuckle bolts torqued to?",a:"The cited 2009 installation procedure specifies 75 lb-ft (102 N·m)."},{q:"When are JK control-arm and track-bar bolts tightened?",a:"The cited suspension procedure requires full vehicle weight on the suspension."},{q:"Can the pinion nut be tightened to a generic chart value?",a:"No. Pinion tightening establishes bearing preload and requires the exact axle procedure and rotating-torque measurements."}]},
};
function makePage(j:Job):SpecRecord{const points=j.diagram==="firing"?(j.values[0]?.value.match(/\d/g)??["ID"]):j.values.map((_,i)=>String(i+1));const record:SpecRecord={slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:j.category,title:j.title,metaDescription:`${j.title} with application chart, generation boundaries, verification steps and official manufacturer lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:j.sources??[j.source],reviewed:j.reviewed??reviewed,featureImage:j.engine?engineImage:vehicleImage,featureOverlay:true,diagram:{type:j.diagram??"main",title:`Interactive ${j.model} specification guide`,caption:"Orientation aid only. Match the VIN, engine, trim and manufacturer document before use.",points},intro:[j.answer,j.scope],steps:[],guides:["identifying-your-exact-vehicle"],sections:[{heading:`Application boundaries for ${j.model}`,paragraphs:[j.scope,j.detail]}],faqs:generalVehicleBatch2Faqs[j.slug]??[{q:`What are the ${j.keyword}?`,a:j.answer},{q:"Why does the specification vary?",a:j.scope},{q:"What should be verified first?",a:`${j.detail} Confirm the exact application in the linked manufacturer source.`}]};const editorial=researchedEditorial[j.slug];if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;record.intro=[record.answer,record.scope,record.detail];}return record;}
export const generalVehicleBatch2Specs:SpecRecord[]=jobs.map(makePage);
